from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_start = None
        self.current_minutes = {}
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_block_date = None
        self.last_equity_warning_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()
        self._handle_expiration_processing(slice)
        self._evaluate_option_exit(slice)
        self._process_spy_minute(slice)

    def _process_spy_minute(self, slice: Slice):
        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        bar_time = minute_bar.Time
        session_time = bar_time.time()

        if session_time < time(9, 30) or session_time >= time(16, 0):
            return

        minutes_from_open = (bar_time.hour - 9) * 60 + bar_time.minute - 30
        bucket_start = bar_time.replace(
            minute=30 + (minutes_from_open // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start
        elif bucket_start != self.current_bucket_start:
            self.current_minutes.clear()
            self.current_bucket_start = bucket_start

        self.current_minutes[bar_time] = minute_bar

        if (bar_time.minute - 30) % 5 != 4:
            return

        if len(self.current_minutes) != 5:
            self.current_minutes.clear()
            return

        ordered = [
            self.current_minutes[
                bucket_start + timedelta(minutes=i)
            ]
            for i in range(5)
            if bucket_start + timedelta(minutes=i) in self.current_minutes
        ]

        if len(ordered) != 5:
            self.current_minutes.clear()
            return

        consolidated = TradeBar(
            bucket_start,
            self.spy,
            ordered[0].Open,
            max(x.High for x in ordered),
            min(x.Low for x in ordered),
            ordered[-1].Close,
            sum(x.Volume for x in ordered)
        )

        self.current_minutes.clear()
        self._process_five_minute_bar(consolidated, slice)

    def _process_five_minute_bar(self, bar: TradeBar, slice: Slice):
        current_fast = None
        current_slow = None

        if len(self.slow_closes) == self.slow_closes.maxlen:
            current_fast = sum(list(self.fast_closes)[-5:]) / 5.0
            current_slow = sum(self.slow_closes) / 20.0

        bullish_crossover = (
            current_fast is not None and
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        self.fast_closes.append(float(bar.Close))
        self.slow_closes.append(float(bar.Close))

        if len(self.fast_closes) == 5:
            self.previous_fast = sum(self.fast_closes) / 5.0

        if len(self.slow_closes) == 20:
            self.previous_slow = sum(self.slow_closes) / 20.0

        bar_end = bar.Time + timedelta(minutes=5)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._attempt_entry(slice)

    def _attempt_entry(self, slice: Slice):
        if self.expiration_block_date == self.Time.date():
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self._has_option_position():
            return

        if not slice.OptionChains:
            self.Debug("Skipped call selection: no option chain.")
            return

        current_price = float(self.Securities[self.spy].Price)
        if current_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        contracts = []
        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                dte = (expiry_date - self.Time.date()).days

                if dte < 1:
                    continue

                contracts.append((expiry_date, contract))

        if not contracts:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        selected_expiry = min(expiry for expiry, _ in contracts)
        minimum_strike = current_price * 1.01

        candidates = [
            contract for expiry, contract in contracts
            if expiry == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Call entry submitted: {} strike {:.2f} expiry {}.".format(
                selected.Symbol,
                float(selected.Strike),
                selected.Expiry.date()
            )
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        quote = self._find_current_option_quote(slice, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _handle_expiration_processing(self, slice: Slice):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        today = self.Time.date()

        if today == expiry_date:
            self.expiration_block_date = today
            if self.Portfolio[self.held_option].Quantity > 0:
                self._submit_exit("expiration protection")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            today == previous_trading_day and
            self.Time.time() >= time(15, 45) and
            self.Portfolio[self.held_option].Quantity > 0
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            if reason == "profit target":
                self.exit_ticket.Cancel("Profit target superseded open exit.")
            else:
                return

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug("Call exit submitted: {}.".format(reason))

    def _find_current_option_quote(self, slice: Slice, symbol):
        for chain in slice.OptionChains.Values:
            if symbol in chain.Contracts:
                contract = chain.Contracts[symbol]
                return float(contract.BidPrice), float(contract.AskPrice)
        return None

    def _handle_unexpected_equity_position(self):
        holdings = self.Portfolio[self.spy].Quantity
        if holdings == 0:
            return

        if self.last_equity_warning_date != self.Time.date():
            self.Debug("Unexpected SPY exercise or assignment position detected.")
            self.last_equity_warning_date = self.Time.date()

        self.MarketOrder(self.spy, -holdings)

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        order_type_text = str(order.Type)
        if "Exercise" in order_type_text or "Assignment" in order_type_text:
            self.Debug("Unexpected option exercise or assignment detected.")

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0 and self.entry_price is None:
                self.held_option = order.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: {} at {:.4f}.".format(
                        order.Symbol,
                        self.entry_price
                    )
                )

            if order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Call position liquidated: {}.".format(order.Symbol))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ]:
                self.exit_ticket = None

    def _has_option_position(self):
        return any(
            security.Type == SecurityType.Option and security.Holdings.Quantity > 0
            for security in self.Securities.Values
        )

    def _ticket_is_open(self, ticket):
        return ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Error
        ]

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

