        self._handle_unexpected_equity_position()
        self._process_option_exit_rules(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._current_slice = slice
        self._update_five_minute_bar(spy_bar)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_end = self.TimeZone.ConvertFromUtc(minute_bar.EndTime)
        if local_end.date() != self.Time.date():
            return

        minute_of_day = local_end.hour * 60 + local_end.minute

        # Regular-session minute bars end from 09:31 through 16:00.
        if minute_of_day < 9 * 60 + 31 or minute_of_day > 16 * 60:
            return

        first_end = 9 * 60 + 35
        bucket_number = (minute_of_day - first_end + 4) // 5
        bucket_end_minute = first_end + bucket_number * 5
        bucket_date = local_end.date()

        if (
            self._bucket_date != bucket_date
            or self._bucket_end_minute != bucket_end_minute
        ):
            self._bucket_date = bucket_date
            self._bucket_end_minute = bucket_end_minute
            self._bucket_bars = {}

        self._bucket_bars[minute_of_day] = minute_bar

        expected_minutes = [
            bucket_end_minute - 4,
            bucket_end_minute - 3,
            bucket_end_minute - 2,
            bucket_end_minute - 1,
            bucket_end_minute
        ]

        if not all(minute in self._bucket_bars for minute in expected_minutes):
            return

        bars = [self._bucket_bars[minute] for minute in expected_minutes]
        five_minute_bar = TradeBar(
            bars[0].EndTime - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self._bucket_bars = {}

        self.fast.Update(five_minute_bar.EndTime, five_minute_bar.Close)
        self.slow.Update(five_minute_bar.EndTime, five_minute_bar.Close)

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        if (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
        ):
            bar_end_local = self.TimeZone.ConvertFromUtc(
                five_minute_bar.EndTime
            )
            eligible_time = (
                bar_end_local.hour * 60 + bar_end_local.minute
            )

            bullish_crossover = (
                self.previous_fast <= self.previous_slow
                and current_fast > current_slow
            )

            if (
                bullish_crossover
                and 9 * 60 + 45 <= eligible_time <= 14 * 60 + 30
            ):
                self._try_enter_call(
                    self._current_slice,
                    five_minute_bar.Close,
                    bar_end_local.date()
                )

