from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(1, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.minute_bars = {}
        self.current_bucket_end = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_date = None
        self.blocked_entry_date = None

        self.SetWarmUp(0)

    def OnData(self, slice: Slice):
        self._liquidate_unexpected_spy_position()

        self._process_expiration()
        self._evaluate_held_option(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_end = minute_bar.EndTime

        if local_end.time() < time(9, 31) or local_end.time() > time(16, 0):
            return

        session_start = datetime.combine(local_end.date(), time(9, 30))
        minutes_from_start = int((local_end - session_start).total_seconds() // 60)

        if minutes_from_start <= 0:
            return

        bucket_end_minutes = ((minutes_from_start + 4) // 5) * 5
        bucket_end = session_start + timedelta(minutes=bucket_end_minutes)
        bucket_start = bucket_end - timedelta(minutes=5)

        if self.current_bucket_end is not None and bucket_end != self.current_bucket_end:
            self._complete_bucket(self.current_bucket_end, slice)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.minute_bars = {}

        self.minute_bars[local_end] = minute_bar

        if local_end == bucket_end:
            self._complete_bucket(bucket_end, slice)
            self.current_bucket_end = None
            self.minute_bars = {}

    def _complete_bucket(self, bucket_end: datetime, slice: Slice):
        bucket_start = bucket_end - timedelta(minutes=5)
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(expected_time not in self.minute_bars for expected_time in expected_times):
            return

        close = self.minute_bars[expected_times[-1]].Close
        self.closes.append(float(close))

        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        previous_fast = sum(self.closes[-self.fast_period - 1:-1]) / self.fast_period
        previous_slow = sum(self.closes[-self.slow_period - 1:-1]) / self.slow_period
        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        local_end_time = bucket_end.time()
        eligible_time = time(9, 45) <= local_end_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._attempt_entry(slice)

    def _attempt_entry(self, slice: Slice):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = float(self.Securities[self.spy].Price)
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        today = self.Time.date()

        # Select the nearest expiration at least 30 calendar days away.
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > today
            and (contract.Expiry.date() - today).days >= 30
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the rule.")
            return

        selected_expiration = expirations[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiration
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiration {1}, strike {2}".format(
                selected.Symbol, selected_expiration, selected.Strike
            )
        )

    def _evaluate_held_option(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        security = self.Securities.get(self.held_option)
        if security is None:
            return

        bid = security.BidPrice
        ask = security.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("profit target")

    def _process_expiration(self):
        if self.held_option is None or self.expiration_date is None:
            return

        current_date = self.Time.date()

        if current_date >= self.expiration_date:
            self.blocked_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        prior_trading_day = self._prior_trading_day(self.expiration_date)

        if current_date == prior_trading_day and self.Time.time() >= time(15, 45):
            self._submit_exit("expiration time stop")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.held_option in self.Portfolio:
            quantity = self.Portfolio[self.held_option].Quantity
        else:
            quantity = 0

        if quantity == 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug("Exit submitted: {0} ({1})".format(self.held_option, reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        symbol = order_event.Symbol

        if self.entry_ticket is not None and symbol == self.entry_ticket.Symbol:
            self.entry_price = float(order_event.FillPrice)
            self.held_option = symbol
            self.expiration_date = symbol.ID.Date.date()
            self.entry_ticket = None

            self.Debug(
                "Entry filled: {0} at {1}".format(symbol, self.entry_price)
            )
            return

        if self.exit_ticket is not None and symbol == self.exit_ticket.Symbol:
            self.Debug("Exit filled: {0} at {1}".format(symbol, order_event.FillPrice))
            self.exit_ticket = None
            self.held_option = None
            self.entry_price = None
            self.expiration_date = None

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentEvent):
        self.Debug("Unexpected exercise or assignment received.")
        self._liquidate_unexpected_spy_position()

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(self.spy, -quantity)

    def _prior_trading_day(self, date_value):
        prior = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(prior):
            prior -= timedelta(days=1)

        return prior

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        )
