        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_end = minute_bar.EndTime

        if local_end.time() < time(9, 31) or local_end.time() > time(16, 0):
            return

        session_start = datetime.combine(local_end.date(), time(9, 30))
        minutes_from_start = int((local_end - session_start).total_seconds() // 60)

        if minutes_from_start <= 0:
            return

        bucket_end_minutes = ((minutes_from_start + 4) // 5) * 5
        bucket_end = session_start + timedelta(minutes=bucket_end_minutes)
        bucket_start = bucket_end - timedelta(minutes=5)

        if self.current_bucket_end is not None and bucket_end != self.current_bucket_end:
            self._complete_bucket(self.current_bucket_end, slice)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.minute_bars = {}

        self.minute_bars[local_end] = minute_bar

        if local_end == bucket_end:
            self._complete_bucket(bucket_end, slice)
            self.current_bucket_end = None
            self.minute_bars = {}

    def _complete_bucket(self, bucket_end: datetime, slice: Slice):
        bucket_start = bucket_end - timedelta(minutes=5)
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(expected_time not in self.minute_bars for expected_time in expected_times):
            return

        close = self.minute_bars[expected_times[-1]].Close
        self.closes.append(float(close))

        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        previous_fast = sum(self.closes[-self.fast_period - 1:-1]) / self.fast_period
        previous_slow = sum(self.closes[-self.slow_period - 1:-1]) / self.slow_period
        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        local_end_time = bucket_end.time()
        eligible_time = time(9, 45) <= local_end_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._attempt_entry(slice)

    def _attempt_entry(self, slice: Slice):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = float(self.Securities[self.spy].Price)
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        today = self.Time.date()

        # Select the nearest expiration at least 30 calendar days away.
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > today
            and (contract.Expiry.date() - today).days >= 30
        })

