from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_symbol = None
        self.entry_fill_price = None
        self.expiration_block_date = None
        self.equity_liquidation_order_id = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position(slice)
        self._process_expiration()
        self._process_option_exit(slice)

        if self.entry_order_id is not None:
            return

        if self.held_symbol is not None:
            return

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        completed = self._add_minute_bar(bar)
        if completed is None:
            return

        self._evaluate_crossover(completed, slice)

    def _add_minute_bar(self, bar):
        end_time = bar.EndTime
        local_date = end_time.date()
        local_time = end_time.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return None

        minute = end_time.minute
        bucket_end_minute = ((minute + 4) // 5) * 5
        if bucket_end_minute == 60:
            bucket_end = end_time.replace(
                hour=end_time.hour + 1,
                minute=0,
                second=0,
                microsecond=0
            )
        else:
            bucket_end = end_time.replace(
                minute=bucket_end_minute,
                second=0,
                microsecond=0
            )

        if bucket_end.time() < time(9, 35) or bucket_end.time() > time(16, 0):
            return None

        if self.bucket_date != local_date or self.bucket_end != bucket_end:
            self.bucket_date = local_date
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end_time] = bar

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if not all(expected in self.bucket_bars for expected in expected_times):
            return None

        bars = [self.bucket_bars[t] for t in expected_times]
        consolidated = TradeBar(
            bucket_end - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

        self.bucket_bars = {}
        return consolidated

    def _evaluate_crossover(self, bar, slice):
        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        previous_closes = self.closes[:-1]
        if len(previous_closes) < self.slow_period:
            return

        previous_fast = (
            sum(previous_closes[-self.fast_period:]) / self.fast_period
        )
        previous_slow = (
            sum(previous_closes[-self.slow_period:]) / self.slow_period
        )

        if not (
            previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            return

        bar_end = bar.EndTime.time()
        if bar_end < time(9, 45) or bar_end > time(14, 30):
            return

        if self.expiration_block_date == self.Time.date():
            return

        self._enter_call(slice, float(bar.Close))

    def _enter_call(self, slice, spy_price):
        chains = list(slice.OptionChains)
        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        today = self.Time.date()
        expirations = set()

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if expiry_date >= today:
                    expirations.add(expiry_date)

        if not expirations:
            self.Debug("Skipped entry: no valid expiration")
            return

        expiration = min(expirations)
        minimum_strike = spy_price * 1.01
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() == expiration
                    and contract.Strike >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call")
            return

        candidates.sort(
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )
        selected = candidates[0]

        ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_order_id = ticket.OrderId
        self.held_symbol = selected.Symbol
        self.entry_fill_price = None

    def _process_option_exit(self, slice):
        if self.held_symbol is None or self.entry_fill_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0 or self.exit_order_id is not None:
            return

        contract = None
        for chain in slice.OptionChains:
            contract = chain.Contracts.get(self.held_symbol)
            if contract is not None:
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.5 * self.entry_fill_price:
            return

        self._submit_exit("50% profit target")

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.expiration_block_date = self.Time.date()
            self._submit_exit("expiration liquidation")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.entry_order_id is not None:
            return

        ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted: " + reason)

    def _handle_unexpected_spy_position(self, slice):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.equity_liquidation_order_id is not None:
            return

        self.Debug("Unexpected SPY exercise or assignment; liquidating equity")
        ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )
        self.equity_liquidation_order_id = ticket.OrderId

    def OnOrderEvent(self, orderEvent):
        order_id = orderEvent.OrderId
        status = orderEvent.Status

        if order_id == self.entry_order_id:
            if status == OrderStatus.Filled:
                self.entry_fill_price = float(orderEvent.FillPrice)
                self.Debug(
                    "Call entry filled: "
                    + str(self.held_symbol)
                    + " @ "
                    + str(self.entry_fill_price)
                )
                self.entry_order_id = None
            elif status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled
            ) and status != OrderStatus.PartiallyFilled:
                self.entry_order_id = None
                self.held_symbol = None
                self.entry_fill_price = None

        if order_id == self.exit_order_id:
            if status == OrderStatus.Filled:
                self.Debug("Call exit filled: " + str(self.held_symbol))
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_fill_price = None
            elif status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

        if order_id == self.equity_liquidation_order_id:
            if status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.equity_liquidation_order_id = None

        if getattr(orderEvent, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment handled")

    def OnEndOfAlgorithm(self):
        if self.held_symbol is not None:
            self.Debug("Algorithm ended with held option: " + str(self.held_symbol))

