from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(lambda universe: universe
                              .IncludeWeeklys()
                              .Strikes(-200, 200)
                              .Expiration(0, 365))

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.current_bucket_start = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_entry_date = None
        self.last_time_stop_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._process_expiration()

        if self.held_option is not None and self.entry_price is not None:
            self._evaluate_profit_target(slice)
            self._evaluate_time_stop()

        bar = slice.Bars.get(self.spy.Symbol)
        if bar is None:
            return

        completed_bar = self._update_five_minute_bar(bar)
        if completed_bar is None:
            return

        self.fast_window.Add(float(completed_bar.Close))
        self.slow_window.Add(float(completed_bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        bar_end = completed_bar.EndTime
        if bar_end.hour < 9 or (bar_end.hour == 9 and bar_end.minute < 45):
            return

        if bar_end.hour > 14 or (bar_end.hour == 14 and bar_end.minute > 30):
            return

        if self.blocked_entry_date == current_date:
            return

        if self.held_option is not None or self._entry_order_open():
            return

        previous_fast = self._previous_average(self.fast_window)
        previous_slow = self._previous_average(self.slow_window)
        current_fast = self._average(self.fast_window)
        current_slow = self._average(self.slow_window)

        if previous_fast <= previous_slow and current_fast > current_slow:
            self._try_enter(slice, float(completed_bar.Close))

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_time = minute_bar.EndTime - timedelta(minutes=1)

        if local_time.hour < 9 or local_time.hour > 16:
            return None

        if local_time.hour == 9 and local_time.minute < 30:
            return None

        if local_time.hour == 16 and local_time.minute > 0:
            return None

        bucket_minute = (local_time.minute // 5) * 5
        bucket_start = datetime(
            local_time.year,
            local_time.month,
            local_time.day,
            local_time.hour,
            bucket_minute
        )

        completed = None

        if self.current_bucket_start is not None and bucket_start != self.current_bucket_start:
            completed = self._complete_bucket()

        if self.current_bucket_start != bucket_start:
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = {}

        self.current_bucket_bars[local_time] = minute_bar
        return completed

    def _complete_bucket(self):
        bars = self.current_bucket_bars

        if self.current_bucket_start.hour == 9 and self.current_bucket_start.minute < 30:
            return None

        expected_times = [
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in bars for t in expected_times):
            return None

        ordered = [bars[t] for t in expected_times]
        return TradeBar(
            self.current_bucket_start,
            self.spy.Symbol,
            ordered[0].Open,
            max(x.High for x in ordered),
            min(x.Low for x in ordered),
            ordered[-1].Close,
            sum(x.Volume for x in ordered),
            timedelta(minutes=5)
        )

    def _try_enter(self, slice: Slice, spy_price: float):
        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() > current_date
        })

        if not expirations:
            self.Debug("Skipped entry: no future expiration satisfies the rule.")
            return

        expiration = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {0}, expiration {1}, strike {2}".format(
                selected.Symbol, expiration, selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_option is None or self.exit_ticket is not None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = next(
            (x for x in chain if x.Symbol == self.held_option),
            None
        )

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.50 * self.entry_price:
            return

        self._cancel_open_exit_order()
        quantity = self.Portfolio[self.held_option].Quantity

        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity,
                tag="50 percent profit target"
            )
            self.Debug(
                "Exit submitted: profit target reached at midpoint {0:.2f}."
                .format(midpoint)
            )

    def _evaluate_time_stop(self):
        if self.held_option is None or self.exit_ticket is not None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        expiry_date = self.held_option.ID.Date.date()
        preceding_date = self._previous_trading_date(expiry_date)

        if self.Time.date() == preceding_date and (
            self.Time.hour > 15 or
            (self.Time.hour == 15 and self.Time.minute >= 45)
        ):
            if self.last_time_stop_date == self.Time.date():
                return

            self.last_time_stop_date = self.Time.date()
            self._cancel_open_exit_order()

            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -holding.Quantity,
                tag="Expiration time stop"
            )
            self.Debug("Exit submitted: expiration time stop.")

    def _process_expiration(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.blocked_entry_date = self.Time.date()
            holding = self.Portfolio[self.held_option]

            if holding.Quantity != 0 and self.exit_ticket is None:
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    -holding.Quantity,
                    tag="Emergency expiration liquidation"
                )
                self.Debug("Exit submitted: option remained at expiration.")

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy.Symbol]
        if holding.Quantity == 0:
            return

        self.blocked_entry_date = self.Time.date()
        self.Debug(
            "Unexpected SPY equity position detected; liquidating immediately."
        )
        self.MarketOrder(
            self.spy.Symbol,
            -holding.Quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def OnAssignmentOrderEvent(self, assignment_event):
        self.blocked_entry_date = self.Time.date()
        self.Debug("Unexpected option exercise or assignment received.")

        holding = self.Portfolio[self.spy.Symbol]
        if holding.Quantity != 0:
            self.MarketOrder(
                self.spy.Symbol,
                -holding.Quantity,
                tag="Exercise or assignment liquidation"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {0} at {1:.4f}."
                    .format(self.held_option, self.entry_price)
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled
            ) and order_event.Status != OrderStatus.PartiallyFilled:
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option exit filled: {0}.".format(self.exit_ticket.Symbol))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _cancel_open_exit_order(self):
        if self.exit_ticket is None:
            return

        if self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            self.exit_ticket.Cancel("Canceling prior exit order.")

    def _previous_trading_date(self, date_value):
        previous = date_value - timedelta(days=1)
        while previous.weekday() >= 5:
            previous -= timedelta(days=1)
        return previous

    def _average(self, window):
        return sum(float(window[i]) for i in range(window.Count)) / window.Count

    def _previous_average(self, window):
        return sum(float(window[i]) for i in range(1, window.Count)) / (window.Count - 1) if window.Count > 1 else 0.0

