        self._no_entry_today = None

        self.Schedule.On(
            self.DateRules.EveryDay(),
            self.TimeRules.At(0, 0),
            self._expiration_processing
        )

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        if self._held_symbol is not None:
            self._evaluate_exit(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        if bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        if bar_time.hour < 9 or (
            bar_time.hour == 9 and bar_time.minute < 30
        ) or bar_time.hour >= 16:
            return

        minute_of_session = (bar_time.hour * 60 + bar_time.minute) - (9 * 60 + 30)
        bucket_minute = (minute_of_session // 5) * 5
        bucket_start = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            9,
            30
        ) + timedelta(minutes=bucket_minute)

        if (
            self._minute_bucket_start is not None
            and bucket_start != self._minute_bucket_start
        ):
            self._finalize_bucket(slice)

        if (
            self._minute_bucket_date is not None
            and self._minute_bucket_date != bar_time.date()
        ):
            self._minute_bucket = {}

        if self._minute_bucket_start != bucket_start:
            self._minute_bucket_start = bucket_start
            self._minute_bucket_date = bar_time.date()
            self._minute_bucket = {}

        self._minute_bucket[bar_time.minute] = bar

    def _finalize_bucket(self, slice: Slice):
        if self._minute_bucket_start is None:
            return

        expected_minutes = [
            self._minute_bucket_start.minute + offset for offset in range(5)
        ]

        if not all(minute in self._minute_bucket for minute in expected_minutes):
            self._minute_bucket = {}
            return

        bars = [self._minute_bucket[minute] for minute in expected_minutes]
        consolidated = TradeBar(
            self._minute_bucket_start,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self._minute_bucket = {}
        self._on_five_minute_bar(consolidated, slice)

    def _on_five_minute_bar(self, bar: TradeBar, slice: Slice):
        if self.slow_window.IsReady:
            previous_fast = sum(self.fast_window[i] for i in range(5)) / 5.0
            previous_slow = sum(self.slow_window[i] for i in range(20)) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.fast_window.Add(bar.Close)
        self.slow_window.Add(bar.Close)

        if not self.slow_window.IsReady:
            return

        current_fast = sum(self.fast_window[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow_window[i] for i in range(20)) / 20.0

        bar_end = bar.EndTime
        if bar_end.tzinfo is not None:
            bar_end = bar_end.replace(tzinfo=None)

        eligible_time = (
            bar_end.hour > 9 or
            (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14 or
            (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        bullish_cross = (
            previous_fast is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_cross and eligible_time:
            self._try_enter(slice, bar.Close)

    def _try_enter(self, slice: Slice, spy_price: float):
        if self._no_entry_today == self.Time.date():
            return

        if self._held_symbol is not None:
            return

        if (
            self._entry_ticket is not None
            and self._entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        ):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        future_contracts = [
            contract for contract in chain
            if contract.Expiry.date() > current_date
        ]

        if not future_contracts:
            self.Debug("Skipped entry: no expiration satisfies the rule.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in future_contracts
        )

        eligible_calls = [
            contract for contract in future_contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not eligible_calls:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(
            eligible_calls,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}.".format(
                selected.Symbol, selected.Expiry.date(), selected.Strike
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self._held_symbol is None or self._exit_submitted:
            return

        holding = self.Portfolio[self._held_symbol]
        if holding.Quantity <= 0:
            return

        now = self.Time
        expiry_date = self._held_symbol.ID.Date.date()

        time_stop = (
            now.hour == 15
            and now.minute >= 45
            and self._is_pre_expiration_trading_day(now.date(), expiry_date)
        )

        profit_target = False
        quote = slice.QuoteBars.get(self._held_symbol)
        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            bid = quote.Bid.Close
            ask = quote.Ask.Close
            if bid > 0 and ask > 0 and self._entry_fill_price is not None:
                midpoint = (bid + ask) / 2.0
                profit_target = midpoint >= 1.50 * self._entry_fill_price

        if profit_target:
            self._submit_exit("50% profit target")
        elif time_stop:
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason: str):
        if self._held_symbol is None or self._exit_submitted:
            return

        holding = self.Portfolio[self._held_symbol]
        if holding.Quantity <= 0:
            return

        if self._exit_ticket is not None:
            if self._exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                self._exit_ticket.Cancel("Replacing exit order")

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -holding.Quantity
        )
        self._exit_submitted = True
        self.Debug("Exit submitted: {0}.".format(reason))

    def _expiration_processing(self):
        if self._held_symbol is None:
            return

        expiry_date = self._held_symbol.ID.Date.date()
        if expiry_date == self.Time.date():
            self._no_entry_today = self.Time.date()
            self._submit_exit("expiration processing")

    def _is_pre_expiration_trading_day(self, current_date, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment: liquidating SPY equity."
            )
            self.MarketOrder(self.spy, -holding.Quantity)

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if (
            self._entry_ticket is not None
            and orderEvent.OrderId == self._entry_ticket.OrderId
        ):
            if orderEvent.Status == OrderStatus.Filled:
                self._held_symbol = orderEvent.Symbol
                self._entry_fill_price = orderEvent.FillPrice
                self._entry_ticket = None
                self._exit_ticket = None
                self._exit_submitted = False
                self.Debug(
                    "Entry filled: {0} at {1}.".format(
                        orderEvent.Symbol, orderEvent.FillPrice
                    )
                )
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and orderEvent.OrderId == self._exit_ticket.OrderId
        ):
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}.".format(
                        orderEvent.Symbol, orderEvent.FillPrice
                    )
                )
                self._exit_ticket = None
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._exit_ticket = None

        if getattr(orderEvent, "IsAssignment", False):
            self.Debug("Unexpected exercise or assignment event received.")
            self._handle_unexpected_equity_position()

