from AlgorithmImports import *
from datetime import datetime, date, time, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast = self.SMA(5)
        self.slow = self.SMA(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol, self.consolidator
        )

        self.previous_fast = None
        self.previous_slow = None
        self.previous_averages_ready = False
        self.pending_signal = False
        self.last_signal_bar = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = bar.EndTime.time()

        previous_fast = float(self.fast.Current.Value) if self.fast.IsReady else None
        previous_slow = float(self.slow.Current.Value) if self.slow.IsReady else None
        previous_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        self.previous_fast = previous_fast
        self.previous_slow = previous_slow
        self.previous_averages_ready = previous_ready

        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and float(self.fast.Current.Value) > float(self.slow.Current.Value)
        )

        if bullish_cross and self.last_signal_bar != bar.EndTime:
            self.pending_signal = True
            self.last_signal_bar = bar.EndTime

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_symbol is not None:
            expiration = self.held_symbol.ID.Date.date()

            if self.Time.date() >= expiration:
                self.no_entry_date = self.Time.date()
                self.SubmitExit("expiration")
            elif (
                self.Time.time() >= time(15, 45)
                and self.IsTradingDayImmediatelyBefore(expiration)
            ):
                self.SubmitExit("time stop")
            else:
                self.CheckProfitTarget(slice)

        if not self.pending_signal:
            return

        self.pending_signal = False

        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self.IsEntryOrderOpen():
            return

        self.TryEnter(slice)

    def TryEnter(self, slice):
        spy_price = float(self.Securities[self.spy_symbol].Price)
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        today = self.Time.date()
        expirations = {}

        for chain in chains:
            for contract in chain.Contracts.Values:
                symbol = contract.Symbol

                if symbol.ID.OptionRight != OptionRight.Call:
                    continue

                expiration = symbol.ID.Date.date()
                dte = (expiration - today).days

                # Select the nearest expiration at least 30 calendar days away.
                if dte >= 30:
                    expirations.setdefault(expiration, []).append(contract)

        if not expirations:
            self.Debug("Skipped selection: no qualifying expiration.")
            return

        selected_expiration = min(expirations.keys())
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in expirations[selected_expiration]
            if contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call strike.")
            return

        candidates.sort(
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} at market, expiration {}.".format(
                selected.Symbol, selected_expiration
            )
        )

    def CheckProfitTarget(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.IsExitOrderOpen():
            return

        contract = self.GetCurrentContract(slice, self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def GetCurrentContract(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = int(holding.Quantity)

        if quantity == 0:
            return

        if self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Replacing exit order")

