            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast = self.SMA(5)
        self.slow = self.SMA(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol, self.consolidator
        )

        self.previous_fast = None
        self.previous_slow = None
        self.previous_averages_ready = False
        self.pending_signal = False
        self.last_signal_bar = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = bar.EndTime.time()

        previous_fast = float(self.fast.Current.Value) if self.fast.IsReady else None
        previous_slow = float(self.slow.Current.Value) if self.slow.IsReady else None
        previous_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        self.previous_fast = previous_fast
        self.previous_slow = previous_slow
        self.previous_averages_ready = previous_ready

        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and float(self.fast.Current.Value) > float(self.slow.Current.Value)
        )

        if bullish_cross and self.last_signal_bar != bar.EndTime:
            self.pending_signal = True
            self.last_signal_bar = bar.EndTime

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_symbol is not None:
            expiration = self.held_symbol.ID.Date.date()

            if self.Time.date() >= expiration:
                self.no_entry_date = self.Time.date()
                self.SubmitExit("expiration")
            elif (
                self.Time.time() >= time(15, 45)
                and self.IsTradingDayImmediatelyBefore(expiration)
            ):
                self.SubmitExit("time stop")
            else:
                self.CheckProfitTarget(slice)

        if not self.pending_signal:
            return

        self.pending_signal = False

        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self.IsEntryOrderOpen():
            return

        self.TryEnter(slice)

