from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    TARGET_DTE = 30

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False).Symbol
        self.spy_security = self.Securities[self.spy]
        self.spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 90)
        )
        self.option_canonical = option.Symbol

        self.closes = deque(maxlen=20)
        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_order_id = None
        self.held_option = None
        self.entry_price = None
        self.exit_order_id = None
        self.time_stop_date = None
        self.expiration_block_date = None
        self.equity_cleanup_submitted = False

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(9, 31),
            self.ProcessExpiration
        )

    def OnData(self, slice: Slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_option is not None:
            self.EvaluateExit(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        end = bar.EndTime
        local_date = end.date()

        if end.hour < 9 or (end.hour == 9 and end.minute <= 30):
            return
        if end.hour > 16 or (end.hour == 16 and end.minute > 0):
            return

        session_start = end.replace(hour=9, minute=30, second=0, microsecond=0)
        elapsed = end - session_start
        slot_number = (elapsed.total_seconds() + 299) // 300
        slot_end = session_start + timedelta(minutes=int(slot_number * 5))

        if self.bucket_end is not None and (
            slot_end != self.bucket_end or slot_end.date() != local_date
        ):
            self.FinalizeFiveMinuteBar()

        if self.bucket_end != slot_end:
            self.bucket_end = slot_end
            self.bucket_bars = {}

        self.bucket_bars[end] = bar

        if len(self.bucket_bars) == 5:
            self.FinalizeFiveMinuteBar()

    def FinalizeFiveMinuteBar(self):
        if self.bucket_end is None:
            return

        bucket_end = self.bucket_end
        bars = self.bucket_bars

        if len(bars) == 5:
            expected = [
                bucket_end - timedelta(minutes=i)
                for i in range(4, -1, -1)
            ]

            if all(timestamp in bars for timestamp in expected):
                close = bars[expected[-1]].Close
                self.ProcessFiveMinuteClose(bucket_end, close)

        self.bucket_end = None
        self.bucket_bars = {}

    def ProcessFiveMinuteClose(self, bar_end, close):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5
            previous_slow = sum(self.closes) / 20

        self.closes.append(float(close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5
        current_slow = sum(self.closes) / 20

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_time = bar_end.time()
        eligible = (
            bar_time.hour > 9 or (bar_time.hour == 9 and bar_time.minute >= 45)
        ) and (
            bar_time.hour < 14 or (bar_time.hour == 14 and bar_time.minute <= 30)
        )

        if bullish_cross and eligible:
            self.TryEnterCall(close)

    def TryEnterCall(self, spy_price):
        today = self.Time.date()

        if self.held_option is not None or self.entry_order_id is not None:
            return
        if self.expiration_block_date == today:
            return

        chains = self.GetOptionChains()
        if not chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        target_expiration = self.Time.date() + timedelta(days=self.TARGET_DTE)
        candidates = []

        for chain in chains:
            for contract in self.GetContracts(chain):
                symbol = contract.Symbol
                if symbol.ID.Date.date() != target_expiration:
                    continue
                if symbol.ID.OptionRight != OptionRight.Call:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue
                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no qualifying expiration/strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug("Call entry submitted: " + str(selected.Symbol))

    def EvaluateExit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        symbol = self.held_option
        bid = None
        ask = None

        if symbol in slice.QuoteBars:
            quote = slice.QuoteBars[symbol]
            if quote.Bid is not None:
                bid = quote.Bid.Close
            if quote.Ask is not None:
                ask = quote.Ask.Close

        if bid is not None and ask is not None and bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2
            if midpoint >= 1.50 * self.entry_price:
                self.SubmitExit("profit target")
                return

        if self.IsTradingDayImmediatelyBeforeExpiration(symbol):
            if self.Time.hour == 15 and self.Time.minute == 45:
                if self.time_stop_date != self.Time.date():
                    self.time_stop_date = self.Time.date()
                    self.SubmitExit("time stop")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
            if ticket is not None and ticket.Status in [
                OrderStatus.New,
                OrderStatus.PartiallyFilled,
                OrderStatus.Submitted,
                OrderStatus.CancelPending
            ]:
                ticket.Cancel("Replaced by " + reason)

        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            quantity = -1

        ticket = self.MarketOrder(self.held_option, quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug("Call exit submitted: " + reason)

    def ProcessExpiration(self):
        today = self.Time.date()

        if self.held_option is not None:
            expiration = self.held_option.ID.Date.date()
            if expiration <= today:
                self.expiration_block_date = today
                self.SubmitExit("expiration processing")

    def IsTradingDayImmediatelyBeforeExpiration(self, symbol):
        expiration = symbol.ID.Date.date()
        current = self.Time.date()

        if current >= expiration:
            return False

        candidate = current + timedelta(days=1)
        while candidate < expiration:
            if self.spy_security.Exchange.Hours.IsDateOpen(candidate):
                return False
            candidate += timedelta(days=1)

        return candidate == expiration

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            if not self.equity_cleanup_submitted:
                self.Debug("Unexpected SPY equity position; liquidating.")
                self.MarketOrder(self.spy, -quantity)
                self.equity_cleanup_submitted = True
        else:
            self.equity_cleanup_submitted = False

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if order_event.OrderId == self.entry_order_id:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.time_stop_date = None
                self.Debug(
                    "Call entry filled: "
                    + str(self.held_option)
                    + " at "
                    + str(self.entry_price)
                )

            elif order_event.OrderId == self.exit_order_id:
                self.Debug("Call exit filled: " + str(order_event.Symbol))
                self.exit_order_id = None
                self.held_option = None
                self.entry_price = None

            if getattr(order_event, "IsAssignment", False):
                self.Debug("Unexpected option exercise or assignment handled.")
                self.HandleUnexpectedEquityPosition()

        elif order_event.OrderId == self.entry_order_id and order_event.Status in [
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            self.Debug("Call entry order did not fill.")
            self.entry_order_id = None

    def GetOptionChains(self):
        result = []
        option_chains = self.CurrentSlice.OptionChains

        for item in option_chains:
            chain = item.Value if hasattr(item, "Value") else item
            result.append(chain)

        return result

    def GetContracts(self, chain):
        contracts = chain.Contracts

        if hasattr(contracts, "Values"):
            return list(contracts.Values)
        if hasattr(contracts, "values"):
            return list(contracts.values())

        return list(contracts)

