        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            if not self.equity_cleanup_submitted:
                self.Debug("Unexpected SPY equity position; liquidating.")
                self.MarketOrder(self.spy, -quantity)
                self.equity_cleanup_submitted = True
        else:
            self.equity_cleanup_submitted = False

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if order_event.OrderId == self.entry_order_id:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.time_stop_date = None
                self.Debug(
                    "Call entry filled: "
                    + str(self.held_option)
                    + " at "
                    + str(self.entry_price)
                )

            elif order_event.OrderId == self.exit_order_id:
                self.Debug("Call exit filled: " + str(order_event.Symbol))
                self.exit_order_id = None
                self.held_option = None
                self.entry_price = None

            if getattr(order_event, "IsAssignment", False):
                self.Debug("Unexpected option exercise or assignment handled.")
                self.HandleUnexpectedEquityPosition()

        elif order_event.OrderId == self.entry_order_id and order_event.Status in [
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            self.Debug("Call entry order did not fill.")
            self.entry_order_id = None

    def GetOptionChains(self):
        result = []
        option_chains = self.CurrentSlice.OptionChains

        for item in option_chains:
            chain = item.Value if hasattr(item, "Value") else item
            result.append(chain)

        return result

    def GetContracts(self, chain):
        contracts = chain.Contracts

        if hasattr(contracts, "Values"):
            return list(contracts.Values)
        if hasattr(contracts, "values"):
            return list(contracts.values())

        return list(contracts)

