        candidates = [
            contract
            for chain in chains
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiration.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.option_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY crossover entry",
        )

    def _evaluate_exit(self, slice):
        if self.option_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.option_symbol]
        if not holding.Invested:
            return

        contract = None
        for chain in slice.OptionChains:
            for candidate in chain:
                if candidate.Symbol == self.option_symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration(self, current_date):
        if self.option_symbol is None:
            return

        holding = self.Portfolio[self.option_symbol]
        if not holding.Invested:
            return

        expiration = self.Securities[self.option_symbol].Symbol.ID.Date.date()

        if current_date >= expiration:
            self.block_entries_today.add(current_date)
            self._submit_exit("expiration protection")
            return

        previous_trading_day = self._previous_trading_day(expiration)
        if (
            current_date == previous_trading_day
            and self.Time.time() >= datetime(2000, 1, 1, 15, 45).time()
        ):
            self._submit_exit("pre-expiration time stop")

    def _previous_trading_day(self, date_value):
        candidate = datetime(
            date_value.year, date_value.month, date_value.day
        ) - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def _submit_exit(self, reason):
        if self.option_symbol is None:
            return

        holding = self.Portfolio[self.option_symbol]
        quantity = int(holding.Quantity)
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            if self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                self.exit_ticket.Cancel("Replacing exit order")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.option_symbol,
            -quantity,
            tag=reason,
        )
        self.Debug("Exit submitted: {0}".format(reason))

    def _handle_unexpected_spy_position(self, current_date):
        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            return

        self.block_entries_today.add(current_date)
        self.Debug(
            "Unexpected SPY exercise/assignment position; liquidating {0}".format(
                holding.Quantity
            )
        )
        self.MarketOrder(
            self.spy,
            -int(holding.Quantity),
            tag="Unexpected exercise or assignment liquidation",
        )

    def _has_option_position(self):
        for holding in self.Portfolio.Values:
            if (
                holding.Invested
                and holding.Symbol.SecurityType == SecurityType.Option
            ):
                return True
        return False

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

