        self._liquidate_unexpected_spy_position()
        self._process_expiration()

        if self.held_option is not None and self._has_option_position():
            self._evaluate_exit(slice)

        bar = slice.Bars[self.spy_symbol] if slice.Bars.ContainsKey(self.spy_symbol) else None
        if bar is not None:
            self._process_minute_bar(bar)

    def _process_minute_bar(self, bar: TradeBar):
        local_end = bar.EndTime
        current_time = local_end.time()

        if current_time < time(9, 31) or current_time > time(16, 0):
            return

        minutes_from_open = (
            current_time.hour * 60 + current_time.minute
        ) - (9 * 60 + 30)

        if minutes_from_open <= 0:
            return

        bucket_number = (minutes_from_open - 1) // 5
        bucket_ending = datetime.combine(
            local_end.date(),
            time(9, 35)
        ) + timedelta(minutes=5 * bucket_number)

        if self._bucket_ending != bucket_ending:
            self._bucket_ending = bucket_ending
            self._bucket_closes = []

        expected_minute = bucket_ending - timedelta(
            minutes=5 - len(self._bucket_closes)
        )

        if local_end != expected_minute:
            self._bucket_closes = [bar.Close]
            return

        self._bucket_closes.append(float(bar.Close))

        if len(self._bucket_closes) == 5:
            close = self._bucket_closes[-1]
            completed_end = self._bucket_ending
            self._bucket_closes = []
            self._on_five_minute_bar(completed_end, close)

