            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call.")
            return

        candidates.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish crossover call entry"
        )
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        quote_contract = None
        if slice.OptionChains.ContainsKey(self.option_symbol):
            chain = slice.OptionChains[self.option_symbol]
            for contract in chain:
                if contract.Symbol == self.held_option:
                    quote_contract = contract
                    break

        if quote_contract is not None:
            bid = float(quote_contract.BidPrice)
            ask = float(quote_contract.AskPrice)

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.50 * self.entry_price:
                    self._submit_exit("50% profit target")
                    return

