    def _try_enter_call(self, spy_price):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.entry_order_id is not None or self.entry_symbol is not None:
            return

        chains = list(self.CurrentSlice.OptionChains)
        if not chains:
