        if "SPY" not in slice.Bars:
            return

        bar = slice.Bars["SPY"]
        bar_time = bar.EndTime
        local_time = bar_time

        if not self._is_regular_session_minute(local_time):
            return

        bucket_end = self._bucket_end(local_time)

        if self.current_bucket is None:
            self.current_bucket = bucket_end
        elif bucket_end != self.current_bucket:
            self._finalize_bucket()
            self.current_bucket = bucket_end
            self.bucket_closes = {}
            self.bucket_minutes = set()

        minute_key = local_time.replace(second=0, microsecond=0)
        self.bucket_minutes.add(minute_key)
        self.bucket_closes[minute_key] = float(bar.Close)

    def _is_regular_session_minute(self, value):
        current = value.time()
        return datetime.strptime("09:30", "%H:%M").time() <= current < datetime.strptime("16:00", "%H:%M").time()

    def _bucket_end(self, value):
        minute_of_day = value.hour * 60 + value.minute
        end_minute = ((minute_of_day + 4) // 5) * 5
