from datetime import datetime, timedelta, time

from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data import SubscriptionDataSource
from QuantConnect.Data.Market import TradeBar
from QuantConnect.Indicators import SimpleMovingAverage
from QuantConnect.Orders import OrderStatus, OrderType
from QuantConnect.Securities import DataNormalizationMode
from QuantConnect.Securities.Option import OptionRight
from QuantConnect consolidators import TradeBarConsolidator


class SpyBullishCallAlgorithm(QCAlgorithm):
    TARGET_DAYS_TO_EXPIRATION = 30
    PROFIT_MULTIPLIER = 1.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.pending_signal = False
        self.entry_order_id = None
        self.exit_order_id = None
        self.held_option = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_option is not None:
            self.EvaluateExit(slice)

        if self.pending_signal:
            self.pending_signal = False
            self.TryEnter(slice)

        if slice.Bars.ContainsKey(self.spy):
            self.consolidator.Update(slice.Bars[self.spy])

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value
        was_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not was_ready or not (self.fast.IsReady and self.slow.IsReady):
            return

        bar_time = bar.EndTime.time()
        if time(9, 45) <= bar_time <= time(14, 30):
            if previous_fast <= previous_slow and self.fast.Current.Value > self.slow.Current.Value:
                self.pending_signal = True

    def TryEnter(self, slice):
        if self.entry_order_id is not None:
            return

        if self.held_option is not None:
            return

        if self.blocked_entry_date == self.Time.date():
            return

        if not slice.Bars.ContainsKey(self.spy):
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        spy_price = slice.Bars[self.spy].Close
        target_expiry = self.Time.date() + timedelta(
            days=self.TARGET_DAYS_TO_EXPIRATION
        )

        candidates = []

        for chain in slice.OptionChains:
            for contract in chain.Value:
                if contract.Expiry.date() != target_expiry:
                    continue

                if contract.Right != OptionRight.Call:
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.held_option = selected.Symbol
        self.entry_order_id = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        ).OrderId

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def EvaluateExit(self, slice):
        symbol = self.held_option
        holding = self.Portfolio[symbol]

        if not holding.Invested:
            return

        expiry = self.Securities[symbol].Symbol.ID.Date.date()

        if self.Time.date() >= expiry:
            self.SubmitExit("expiration protection")
            return

        if (
            self.Time.date() == expiry - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("expiration time stop")
            return

        if self.exit_order_id is not None:
            return

        if not slice.QuoteBars.ContainsKey(symbol):
            return

        quote = slice.QuoteBars[symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= self.PROFIT_MULTIPLIER * self.entry_price:
            self.CancelOpenExitOrders(symbol)
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.CancelOpenExitOrders(self.held_option)
        self.exit_order_id = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        ).OrderId

        self.Debug("Exit submitted: {0} ({1})".format(self.held_option, reason))

    def CancelOpenExitOrders(self, symbol):
        for order in self.Transactions.GetOpenOrders(symbol):
            if order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id)

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy]

        if holding.Invested:
            self.Debug(
                "Unexpected exercise or assignment handling: liquidating SPY equity."
            )
            self.Liquidate(self.spy, "Unexpected exercise or assignment")

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)

        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = self.Portfolio[order.Symbol].AveragePrice
                self.entry_order_id = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        order.Symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.InteractiveOrderError
            ):
                self.Debug("Entry order failed or was canceled: {0}".format(order.Symbol))
                self.entry_order_id = None
                self.held_option = None
                self.entry_price = None

        elif order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order.Symbol,
                        order_event.FillPrice
                    )
                )
                self.exit_order_id = None
                self.held_option = None
                self.entry_price = None
                self.blocked_entry_date = self.Time.date()
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.InteractiveOrderError
            ):
                self.exit_order_id = None

        if order_event.OrderType == OrderType.OptionExercise:
            self.Debug("Unexpected option exercise or assignment event received.")
            self.Liquidate(self.spy, "Unexpected option exercise or assignment")
