        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exited {self.option_symbol.Value} "
                    f"at {order_event.FillPrice:.4f}"
                )
                self.exit_ticket = None
                self.entry_ticket = None
                self.entry_price = None
                self.expiration_stop_date = None

        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        is_exercise = (
            getattr(order_event, "OrderType", None) == OrderType.OptionExercise
        )

        if is_assignment or is_exercise:
            self.blocked_entry_date = self.Time.date()
            self.Debug(f"{self.Time}: unexpected exercise or assignment handling")
            self._handle_unexpected_underlying_position()

    def _expiration_check(self):
        symbol = self.option_symbol
        if symbol is None:
            return

        if not self.Portfolio[symbol].Invested:
