        expiry = self.Securities[symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self.blocked_entry_date = self.Time.date()
            self._submit_exit("expiration protection")

    def _handle_unexpected_underlying_position(self):
        holding = self.Portfolio[self.spy]
        if not holding.Invested:
            return

        if (
            self.underlying_liquidation_ticket is not None and
            self.underlying_liquidation_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        ):
            return

        self.blocked_entry_date = self.Time.date()
        self.Debug(f"{self.Time}: unexpected SPY equity position; liquidating")
        self.underlying_liquidation_ticket = self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False
        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False
        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)
        return candidate

