class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    TARGET_DTE = 30

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 365)
        )
        self.option = option

        self.interval_start = None
        self.interval_closes = []
        self.fast_values = []
        self.slow_values = []
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entry_date = None

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        if self._has_unexpected_spy_position():
            return

        if self.held_symbol is not None:
            expiry_date = self._held_expiry_date()
            if expiry_date is not None and current_date >= expiry_date:
                self.no_entry_date = current_date
                self._submit_exit("expiration processing")
            else:
                self._evaluate_held_position(data)

        if self.spy in data.Bars:
            bar = data.Bars[self.spy]
            self._process_minute_bar(bar, data)

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_symbol = self.entry_symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {0}, price {1:.4f}".format(
                        self.held_symbol, self.entry_price
                    )
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    "Exit filled: {0}, price {1:.4f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.entry_symbol = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option assignment/exercise handling.")
            self._liquidate_spy_position()

        if str(order_event.OrderType).lower() in ("optionexercise", "optionassignment"):
            self.Debug("Unexpected option exercise/assignment handling.")
            self._liquidate_spy_position()

    def _process_minute_bar(self, bar, data):
        end_time = bar.EndTime
        session_start = end_time.replace(hour=9, minute=30, second=0, microsecond=0)
        session_end = end_time.replace(hour=16, minute=0, second=0, microsecond=0)

        if end_time <= session_start or end_time > session_end:
            return

        elapsed_minutes = int((end_time - session_start).total_seconds() / 60)
        interval_end = session_start + timedelta(
            minutes=((elapsed_minutes + 4) // 5) * 5
        )
        interval_start = interval_end - timedelta(minutes=5)

        if self.interval_start is not None and interval_start != self.interval_start:
            self.interval_start = interval_start
            self.interval_closes = []

        if self.interval_start is None:
            self.interval_start = interval_start
            self.interval_closes = []

        self.interval_closes.append(float(bar.Close))

        if len(self.interval_closes) != 5:
            return

        close = self.interval_closes[-1]
        completed_end = interval_end

        self.interval_start = None
        self.interval_closes = []

        self._process_five_minute_close(close, completed_end, data)

    def _process_five_minute_close(self, close, bar_end, data):
        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) > 5:
            self.fast_values.pop(0)
        if len(self.slow_values) > 20:
            self.slow_values.pop(0)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        fast = sum(self.fast_values) / 5.0
        slow = sum(self.slow_values) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        eligible_time = (
            bar_end.hour > 9
            or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14
            or (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        if bullish_cross and eligible_time:
            self._try_enter(data, close, bar_end.date())

    def _try_enter(self, data, spy_price, signal_date):
        if self.no_entry_date == signal_date:
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        chains = list(data.OptionChains)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        target_expiry = signal_date + timedelta(days=self.TARGET_DTE)
        matching_contracts = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                dte = (expiry_date - signal_date).days

                if (
                    dte == self.TARGET_DTE
                    and contract.Right == OptionRight.Call
                ):
                    matching_contracts.append(contract)

        if not matching_contracts:
            self.Debug("Skipped entry: no expiration satisfies the DTE rule.")
            return

        eligible = [
            contract for contract in matching_contracts
            if contract.Strike >= 1.01 * spy_price
        ]

        if not eligible:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        eligible.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))
        selected = eligible[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {0}, strike {1}, expiry {2}".format(
                selected.Symbol,
                selected.Strike,
                selected.Expiry.date()
            )
        )

    def _evaluate_held_position(self, data):
        if self.held_symbol is None or self.entry_price is None:
            return

        expiry_date = self._held_expiry_date()
        if expiry_date is None:
            return

        current_date = self.Time.date()
        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            current_date == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("expiration time stop")
            return

        contract = None
        for chain in data.OptionChains:
            for candidate in chain:
                if candidate.Symbol == self.held_symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_order_open():
            self.exit_ticket.Cancel("Replacing exit order: " + reason)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {0}".format(reason))

    def _held_expiry_date(self):
        if self.held_symbol is None:
            return None
        return self.Securities[self.held_symbol].Symbol.ID.Date.date()

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _has_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self._liquidate_spy_position()
            self.no_entry_date = self.Time.date()
            return True
        return False

    def _liquidate_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
