from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-500, 500)
            .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False
        self.pending_signal_time = None

        self.entry_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.entry_expiry = None
        self.expiration_day_blocked = None
        self.spy_liquidation_sent = False

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = bar.EndTime.time()

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if self.fast.IsReady and self.slow.IsReady:
            current_fast = float(self.fast.Current.Value)
            current_slow = float(self.slow.Current.Value)

            if self.previous_fast is not None and self.previous_slow is not None:
                eligible_time = time(9, 45) <= bar_time <= time(14, 30)
                bullish = (
                    self.previous_fast <= self.previous_slow
                    and current_fast > current_slow
                )

                if eligible_time and bullish:
                    self.pending_signal = True
                    self.pending_signal_time = bar.EndTime

            self.previous_fast = current_fast
            self.previous_slow = current_slow

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        current_date = self.Time.date()

        if self.held_symbol is not None and self.entry_expiry is not None:
            if current_date >= self.entry_expiry:
                self.expiration_day_blocked = current_date
                self.SubmitOptionExit("expiration processing")
            elif (
                self.Time.time() >= time(15, 45)
                and self.IsTradingDayImmediatelyBeforeExpiration(
                    current_date, self.entry_expiry
                )
            ):
                self.SubmitOptionExit("expiration eve time stop")
            else:
                self.CheckProfitTarget(slice)

        if self.pending_signal:
            signal_time = self.pending_signal_time
            self.pending_signal = False
            self.pending_signal_time = None

            if self.expiration_day_blocked == current_date:
                return

            if self.held_symbol is not None or self.IsEntryOrderOpen():
                return

            if self.entry_ticket is not None:
                return

            self.TryEnterFromOptionChain(slice, signal_time)

    def TryEnterFromOptionChain(self, slice, signal_time):
        if not slice.OptionChains:
            self.Debug("Skipped call selection: no option chain")
            return

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price")
            return

        calls = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry = contract.Expiry.date()
                dte = (expiry - self.Time.date()).days
                if dte <= 0:
                    continue

                calls.append((contract, expiry, dte))

        if not calls:
            self.Debug("Skipped call selection: no eligible call expiration")
            return

        selected_expiry = min(
            expiry for _, expiry, _ in calls
        )

        eligible_strike = 1.01 * spy_price
        candidates = [
            contract
            for contract, expiry, _ in calls
            if expiry == selected_expiry
            and contract.Strike >= eligible_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying strike")
            return

