from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice):
        self._handle_unexpected_equity_position()
        self._handle_expiration_processing()

        self._evaluate_exit(slice)

        bar = slice.Bars.get(self.spy.Symbol)
        if bar is not None:
            self._process_minute_bar(bar)

    def _process_minute_bar(self, bar):
        local_time = self.Time.replace(second=0, microsecond=0)

        if local_time.time() <= time(9, 30) or local_time.time() > time(16, 0):
            return

        minutes_from_open = (
            local_time.hour * 60 + local_time.minute
        ) - (9 * 60 + 30)

        end_minutes = ((minutes_from_open + 4) // 5) * 5 + (9 * 60 + 30)
        end_hour = end_minutes // 60
        end_minute = end_minutes % 60
        current_end = local_time.replace(
            hour=end_hour,
            minute=end_minute
        )

        if self.bucket_end != current_end:
            self.bucket_end = current_end
            self.bucket = {
                "count": 0,
                "open": bar.Open,
                "high": bar.High,
                "low": bar.Low,
                "close": bar.Close
            }

        self.bucket["count"] += 1
        self.bucket["high"] = max(self.bucket["high"], bar.High)
        self.bucket["low"] = min(self.bucket["low"], bar.Low)
        self.bucket["close"] = bar.Close

        if self.bucket["count"] != 5:
            return

        consolidated_close = self.bucket["close"]
        completed_end = self.bucket_end
        self.bucket = None

        old_fast = self.previous_fast
        old_slow = self.previous_slow

        self.closes.append(consolidated_close)

        if len(self.closes) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bullish_cross = (
            old_fast is not None and
            old_slow is not None and
            old_fast <= old_slow and
            current_fast > current_slow
        )

        eligible_time = time(9, 45) <= completed_end.time() <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter(consolidated_close)

    def _try_enter(self, spy_price):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self._entry_order_open():
            return

        if self._has_option_holding():
            return

        option_chain = None
        for key, chain in self.CurrentSlice.OptionChains.items():
            if key == self.spy_option.Symbol or chain.Symbol == self.spy_option.Symbol:
                option_chain = chain
                break

        if option_chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        expirations = sorted({
            contract.Expiry.date()
            for contract in option_chain.Contracts.Values
            if contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug("Skipped entry: no valid expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in option_chain.Contracts.Values
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.held_symbol = selected.Symbol
        self.entry_price = None

        self.Debug(
            "Entry submitted: {} exp {} strike {:.2f}".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike
            )
        )

    def _evaluate_exit(self, slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self._exit_order_open():
            return

        quote = slice.BidAsks.get(self.held_symbol)
        if quote is not None:
            bid = quote.Bid.Close if quote.Bid is not None else 0
            ask = quote.Ask.Close if quote.Ask is not None else 0

            if (
                self.entry_price is not None and
                bid > 0 and
                ask > 0
            ):
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.5 * self.entry_price:
                    self._submit_exit("profit target")
                    return

        expiry_date = self.held_symbol.ID.Date.date()
        prior_trading_day = self._prior_trading_day(expiry_date)

        if (
            self.Time.date() == prior_trading_day and
            self.Time.hour == 15 and
            self.Time.minute == 45
        ):
            self._submit_exit("expiration time stop")

    def _handle_expiration_processing(self):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            if not self._exit_order_open():
                self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = int(holding.Quantity)

        if quantity == 0:
            return

        if self._exit_order_open():
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.Debug("Exit submitted: {}".format(reason))

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.held_symbol = None
                self.entry_price = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        is_assignment = getattr(order_event, "IsAssignment", False)
        is_exercise = getattr(
            order_event,
            "OrderType",
            None
        ) == OrderType.OptionExercise

        if is_assignment or is_exercise:
            self.Debug("Unexpected option exercise or assignment handled.")
            self._liquidate_spy_equity()

    def _handle_unexpected_equity_position(self):
        if self.Portfolio[self.spy.Symbol].Invested:
            self.Debug("Unexpected SPY equity position liquidated.")
            self._liquidate_spy_equity()

    def _liquidate_spy_equity(self):
        quantity = int(self.Portfolio[self.spy.Symbol].Quantity)
        if quantity != 0:
            self.MarketOrder(self.spy.Symbol, -quantity)

    def _has_option_holding(self):
        return any(
            security.Invested and
            security.Symbol.SecurityType == SecurityType.Option
            for security in self.Portfolio.Values
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _prior_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while True:
            candidate_datetime = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )
            if self.spy.Exchange.Hours.IsDateOpen(candidate_datetime):
                return candidate
            candidate -= timedelta(days=1)

