    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.held_symbol = None
                self.entry_price = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        is_assignment = getattr(order_event, "IsAssignment", False)
        is_exercise = getattr(
            order_event,
            "OrderType",
            None
        ) == OrderType.OptionExercise

        if is_assignment or is_exercise:
            self.Debug("Unexpected option exercise or assignment handled.")
            self._liquidate_spy_equity()

    def _handle_unexpected_equity_position(self):
        if self.Portfolio[self.spy.Symbol].Invested:
            self.Debug("Unexpected SPY equity position liquidated.")
            self._liquidate_spy_equity()

    def _liquidate_spy_equity(self):
        quantity = int(self.Portfolio[self.spy.Symbol].Quantity)
        if quantity != 0:
            self.MarketOrder(self.spy.Symbol, -quantity)

    def _has_option_holding(self):
        return any(
            security.Invested and
            security.Symbol.SecurityType == SecurityType.Option
            for security in self.Portfolio.Values
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _prior_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while True:
            candidate_datetime = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )
            if self.spy.Exchange.Hours.IsDateOpen(candidate_datetime):
                return candidate
            candidate -= timedelta(days=1)

