from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )
        self.option_canonical = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.bucket_date = None
        self.bucket_start_minute = None
        self.bucket_bars = {}

        self.pending_signal = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_date = None
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        current_date = self.Time.date()

        if self.held_symbol is not None:
            expiration_date = self._expiration_date(self.held_symbol)

            if expiration_date is not None and current_date >= expiration_date:
                self.blocked_entry_date = current_date
                self._submit_exit("expiration processing")
            else:
                self._evaluate_time_stop(current_date)
                self._evaluate_profit_target(slice)

        self._process_minute_bar(slice)

        if self.pending_signal is not None:
            signal_time = self.pending_signal
            self.pending_signal = None

            if (
                self.held_symbol is None
                and self.entry_ticket is None
                and current_date != self.blocked_entry_date
            ):
                self._try_enter(slice, signal_time)

    def _process_minute_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        local_time = bar.Time

        if local_time.date() != self.bucket_date:
            self._finalize_bucket()
            self.bucket_date = local_time.date()
            self.bucket_start_minute = None
            self.bucket_bars = {}

        minute = local_time.hour * 60 + local_time.minute

        if minute < 9 * 60 + 30 or minute >= 16 * 60:
            self._finalize_bucket()
            self.bucket_start_minute = None
            self.bucket_bars = {}
            return

        bucket_start = 9 * 60 + 30 + ((minute - (9 * 60 + 30)) // 5) * 5

        if self.bucket_start_minute is None:
            self.bucket_start_minute = bucket_start
        elif bucket_start != self.bucket_start_minute:
            self._finalize_bucket()
            self.bucket_start_minute = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[minute] = bar

    def _finalize_bucket(self):
        if self.bucket_start_minute is None:
            return

        expected = set(
            range(self.bucket_start_minute, self.bucket_start_minute + 5)
        )

        if set(self.bucket_bars.keys()) != expected:
            self.bucket_bars = {}
            return

        last_minute = self.bucket_start_minute + 4
        close = float(self.bucket_bars[last_minute].Close)

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes) / self.slow_period

        self.closes.append(close)

        if len(self.closes) >= self.slow_period:
            current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            current_slow = sum(self.closes) / self.slow_period

            end_hour = (self.bucket_start_minute + 5) // 60
            end_minute = (self.bucket_start_minute + 5) % 60

            eligible = (
                (end_hour > 9 or (end_hour == 9 and end_minute >= 45))
                and (end_hour < 14 or (end_hour == 14 and end_minute <= 30))
            )

            if (
                eligible
                and previous_fast <= previous_slow
                and current_fast > current_slow
            ):
                self.pending_signal = (
                    self.Time.replace(
                        hour=end_hour,
                        minute=end_minute,
                        second=0,
                        microsecond=0
                    )
                )

        self.bucket_bars = {}

    def _try_enter(self, slice: Slice, signal_time):
        if self.option_canonical not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_price = float(self.Securities[self.spy].Price)
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        today = self.Time.date()
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                symbol = contract.Symbol
                expiration = self._expiration_date(symbol)

                if expiration is None:
                    continue

                days_to_expiration = (expiration - today).days

                if (
                    days_to_expiration >= 1
                    and symbol.ID.OptionRight == OptionRight.Call
                ):
                    candidates.append((expiration, contract))

        if not candidates:
            self.Debug("Skipped entry: no valid call expiration.")
            return

        expiration = min(item[0] for item in candidates)
        threshold = current_price * 1.01

        contracts = [
            contract
            for contract_date, contract in candidates
            if contract_date == expiration
            and float(contract.Strike) >= threshold
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            contracts,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover call entry"
        )

        self.Debug(
            "Entry submitted: {0}, strike {1}, expiration {2}".format(
                selected.Symbol,
                selected.Strike,
                expiration
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            return

        contract = None

        if self.option_canonical in slice.OptionChains:
            for chain_contract in slice.OptionChains[self.option_canonical].Contracts.Values:
                if chain_contract.Symbol == self.held_symbol:
                    contract = chain_contract
                    break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= self.entry_price * 1.50:
            self._submit_exit("50 percent profit target")

    def _evaluate_time_stop(self, current_date):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        expiration = self._expiration_date(self.held_symbol)
        if expiration is None:
            return

        previous_trading_day = expiration - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        if current_date == previous_trading_day:
            if self.Time.hour > 15 or (
                self.Time.hour == 15 and self.Time.minute >= 45
            ):
                self._submit_exit("expiration-eve time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if order.Id != (self.entry_ticket.OrderId if self.entry_ticket else -1):
                self.Transactions.CancelOrder(order.Id, "Replacing exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -quantity,
                tag=reason
            )
            self.Debug(
                "Exit submitted: {0}, quantity {1}".format(
                    reason,
                    quantity
                )
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)

        if order.Type == OrderType.OptionExercise:
            self.Debug("Unexpected option exercise or assignment detected.")
            self._liquidate_spy_position()

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order canceled or invalid.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0}".format(order_event.Symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY equity position detected.")
            self._liquidate_spy_position()

    def _liquidate_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0 and self.spy_liquidation_ticket is None:
            self.spy_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _expiration_date(self, symbol):
        try:
            return symbol.ID.Date.date()
        except Exception:
            return None

