from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self._bucket_start = None
        self._minute_bars = {}

        self._fast_closes = []
        self._slow_closes = []

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._blocked_entry_date = None
        self._assignment_ticket = None

    def OnData(self, slice: Slice):
        now = self.Time
        current_date = now.date()

        # Assignment/exercise handling must never become a strategy position.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            if self._assignment_ticket is None:
                self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
                self._assignment_ticket = self.MarketOrder(
                    self.spy,
                    -spy_quantity,
                    "Liquidate unexpected exercise or assignment"
                )

        # Prevent holding an option into or beyond expiration.
        if self._held_symbol is not None:
            expiration_date = self._held_symbol.ID.Date.date()
            if current_date >= expiration_date:
                self._blocked_entry_date = current_date
                self._submit_exit("Expiration protection")

        # Evaluate exits on every minute Slice.
        self._evaluate_option_exit(slice)

        if self.spy not in slice.Bars:
            return

        spy_bar = slice.Bars[self.spy]
        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        local_date = end_time.date()
        end_minutes = end_time.hour * 60 + end_time.minute

        # Regular-session minute bars only. The first bucket ends at 09:35.
        if end_minutes < 9 * 60 + 31 or end_minutes > 16 * 60:
            return

        first_end_minutes = 9 * 60 + 31
        bucket_index = (end_minutes - first_end_minutes) // 5
        bucket_end = datetime.combine(
            local_date,
            time(9, 35)
        ) + timedelta(minutes=5 * bucket_index)
        bucket_start = bucket_end - timedelta(minutes=5)

        if self._bucket_start is not None and bucket_start != self._bucket_start:
            self._minute_bars.clear()

        if self._bucket_start != bucket_start:
            self._bucket_start = bucket_start
            self._minute_bars.clear()

        self._minute_bars[end_time] = bar

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if not all(t in self._minute_bars for t in expected_times):
            return

        bars = [self._minute_bars[t] for t in expected_times]
        consolidated = TradeBar(
            bucket_start,
            self.spy,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

        self._minute_bars.clear()
        self._on_five_minute_bar(consolidated, slice)

    def _on_five_minute_bar(self, bar: TradeBar, slice: Slice):
        previous_fast = None
        previous_slow = None

        if len(self._fast_closes) >= 5:
            previous_fast = sum(self._fast_closes[-5:]) / 5.0
        if len(self._slow_closes) >= 20:
            previous_slow = sum(self._slow_closes[-20:]) / 20.0

        self._fast_closes.append(float(bar.Close))
        self._slow_closes.append(float(bar.Close))

        current_fast = None
        current_slow = None

        if len(self._fast_closes) >= 5:
            current_fast = sum(self._fast_closes[-5:]) / 5.0
        if len(self._slow_closes) >= 20:
            current_slow = sum(self._slow_closes[-20:]) / 20.0

        if (
            previous_fast is None or
            previous_slow is None or
            current_fast is None or
            current_slow is None
        ):
            return

        bar_end = bar.EndTime.time()
        if not (time(9, 45) <= bar_end <= time(14, 30)):
            return

        bullish_crossover = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_crossover:
            self._try_enter(slice, float(bar.Close))

    def _try_enter(self, slice: Slice, spy_price: float):
        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None and self._is_open(self._entry_ticket):
            return

        if self._blocked_entry_date == self.Time.date():
            return

        if not slice.OptionChains:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        # The stated rules do not specify a target DTE, so use the nearest
        # future expiration, excluding same-day expiration.
        expiration_dates = set()
        for chain in chains:
            for contract in chain.Contracts.Values:
                if contract.Right == OptionRight.Call:
                    dte = contract.Expiry.date() - self.Time.date()
                    if dte.days >= 1:
                        expiration_dates.add(contract.Expiry.date())

        if not expiration_dates:
            self.Debug("Skipped call selection: no valid future expiration.")
            return

        selected_expiration = min(expiration_dates)
        minimum_strike = 1.01 * spy_price

        candidates = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call and
                    contract.Expiry.date() == selected_expiration and
                    contract.Strike >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            "Bullish five-minute MA crossover"
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if holding.Quantity <= 0:
            return

        expiration_date = self._held_symbol.ID.Date.date()
        today = self.Time.date()

        if today == self._previous_trading_day(expiration_date):
            if self.Time.time() >= time(15, 45):
                if self._exit_ticket is None or not self._is_open(self._exit_ticket):
                    self._submit_exit("Pre-expiration time stop")
                return

        if self._exit_ticket is not None and self._is_open(self._exit_ticket):
            return

        contract = self._get_current_contract(slice, self._held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * float(self._entry_price):
            self._submit_exit("50 percent profit target")

    def _get_current_contract(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            if symbol in chain.Contracts:
                return chain.Contracts[symbol]
        return None

    def _submit_exit(self, tag: str):
        if self._held_symbol is None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        if self._exit_ticket is not None and self._is_open(self._exit_ticket):
            self._exit_ticket.Cancel("Replacing open exit order")

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _is_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self._entry_ticket is not None and
                order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._held_symbol = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_ticket = None
                self.Debug(
                    "Entered 1 call: {} at {:.2f}".format(
                        self._held_symbol,
                        self._entry_price
                    )
                )

            elif (
                self._exit_ticket is not None and
                order_event.OrderId == self._exit_ticket.OrderId
            ):
                self.Debug(
                    "Exited call: {} at {:.2f}".format(
                        order_event.Symbol,
                        float(order_event.FillPrice)
                    )
                )
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None

            elif (
                self._assignment_ticket is not None and
                order_event.OrderId == self._assignment_ticket.OrderId
            ):
                self.Debug("Unexpected SPY exercise or assignment liquidation filled.")
                self._assignment_ticket = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Error
        ):
            if (
                self._entry_ticket is not None and
                order_event.OrderId == self._entry_ticket.OrderId
            ):
                self.Debug("Call entry order was not filled.")
                self._entry_ticket = None

            elif (
                self._exit_ticket is not None and
                order_event.OrderId == self._exit_ticket.OrderId
            ):
                self._exit_ticket = None

            elif (
                self._assignment_ticket is not None and
                order_event.OrderId == self._assignment_ticket.OrderId
            ):
                self._assignment_ticket = None

