        self.option = option
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self._previous_fast = None
        self._previous_slow = None

        self._current_slice = None
        self._pending_entry_signal = False
        self._entry_ticket = None
        self._exit_ticket = None
        self._entry_price = None
        self._held_option = None
        self._no_entry_date = None
        self._equity_liquidation_ticket = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = self.TimeToNewYork(bar.EndTime)

        if bar_time.time() < datetime.strptime("09:35", "%H:%M").time():
            return

        if bar_time.time() > datetime.strptime("16:00", "%H:%M").time():
            return

        if self.fast.IsReady and self.slow.IsReady:
            previous_fast = self.fast.Current.Value
            previous_slow = self.slow.Current.Value
        else:
            previous_fast = None
            previous_slow = None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if previous_fast is None or previous_slow is None:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if (
            previous_fast <= previous_slow
            and current_fast > current_slow
            and eligible_start <= bar_time.time() <= eligible_end
        ):
            self._pending_entry_signal = True

    def OnData(self, slice):
        self._current_slice = slice
        today = self.Time.date()

        if self.Portfolio[self.spy].Invested:
            if self._equity_liquidation_ticket is None:
                self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
                self._equity_liquidation_ticket = self.Liquidate(
                    self.spy,
                    tag="Unexpected exercise or assignment"
                )

        if self._held_option is not None:
            expiry = self._held_option.ID.Date.date()

            if today >= expiry:
                self._no_entry_date = today
                self._submit_exit("Expiration protection")
            else:
                stop_date = self._previous_trading_date(expiry)
                if (
                    today == stop_date
                    and self.Time.time() >= datetime.strptime("15:45", "%H:%M").time()
                ):
                    self._submit_exit("Expiration time stop")
                else:
                    self._check_profit_target(slice)

        if (
            self._pending_entry_signal
            and today != self._no_entry_date
            and not self.Portfolio.Invested
            and not self._has_open_entry_order()
        ):
            self._pending_entry_signal = False
            self._try_enter(slice)

    def _try_enter(self, slice):
        if self.spy not in self.Securities:
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chain = None
        for symbol, candidate in slice.OptionChains.items():
            if symbol == self.option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        contracts = list(chain.Contracts.Values)
        expirations = sorted({
            contract.ID.Date.date()
            for contract in contracts
            if contract.ID.Date.date() > self.Time.date()
        })

        if not expirations:
            self.Debug("Skipped selection: no valid future expiration.")
            return

        expiration = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
