        self._process_minute_bar(minute_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        bar_time = minute_bar.Time.replace(second=0, microsecond=0)
        local_time = bar_time.time()

        if local_time < datetime.time(9, 30) or local_time >= datetime.time(16, 0):
            return

        minute_index = (bar_time.hour * 60 + bar_time.minute) - (9 * 60 + 30)
        bucket_start = bar_time - timedelta(minutes=minute_index % 5)

