            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

        if len(self.bucket_bars) == 5:
            expected = [
                self.bucket_start + timedelta(minutes=i)
                for i in range(5)
            ]

            actual = [
                bar.Time.replace(second=0, microsecond=0)
                for bar in self.bucket_bars
            ]

            if actual == expected:
                self._emit_five_minute_bar(slice)

            self.bucket_start = None
            self.bucket_bars = []

