            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        if self._is_trading_day_before_expiration(current_date, expiry_date):
            if self.Time.time() >= datetime.time(15, 45):
                self._liquidate_option("expiration time stop")
                return

        if self.entry_price is None or self.entry_price <= 0:
            return

        if self.entry_symbol not in slice.BidPrices:
            return
        if self.entry_symbol not in slice.AskPrices:
            return

        bid = float(slice.BidPrices[self.entry_symbol])
        ask = float(slice.AskPrices[self.entry_symbol])

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50 percent profit target")

    def _liquidate_option(self, reason):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            self.exit_ticket.Cancel("Superseded by {}".format(reason))

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -holding.Quantity,
            tag=reason,
        )
        self.Debug("Exit submitted: {}".format(reason))

    def _is_trading_day_before_expiration(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        next_date = current_date + timedelta(days=1)
        while next_date < expiry_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(next_date):
                return False
            next_date += timedelta(days=1)

        return next_date == expiry_date

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.Debug("Unexpected exercise or assignment: liquidating SPY equity")
        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment handling",
        )

