from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.time_stop_submitted = False
        self.no_entry_date = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_bars = {}

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._process_expiration()

        bar = slice.Bars[self.spy] if self.spy in slice.Bars else None
        if bar is not None:
            self._process_spy_minute(bar, slice)

        self._process_option_exit(slice)

    def _process_spy_minute(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time
        current_date = local_time.date()
        current_clock = local_time.time()

        if current_clock < time(9, 30) or current_clock >= time(16, 0):
            return

        bucket_minute = (local_time.minute // 5) * 5
        bucket_start = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            local_time.hour,
            bucket_minute
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._complete_bucket(slice)

        if self.bucket_date != current_date or self.bucket_start != bucket_start:
            self.bucket_date = current_date
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        minute_key = local_time.replace(second=0, microsecond=0)
        self.bucket_bars[minute_key] = bar

    def _complete_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(minute not in self.bucket_bars for minute in expected):
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[minute] for minute in expected]
        consolidated = TradeBar(
            self.bucket_start,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(consolidated.EndTime, consolidated.Close)
        self.slow.Update(consolidated.EndTime, consolidated.Close)

        if (
            previous_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            end_clock = consolidated.EndTime.time()
            if time(9, 45) <= end_clock <= time(14, 30):
                self._evaluate_entry(slice, consolidated.Close)

        self.bucket_bars = {}

    def _evaluate_entry(self, slice: Slice, spy_price: float):
        if self.no_entry_date == self.Time.date():
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.held_symbol is not None:
            holding = self.Portfolio[self.held_symbol]
            if holding.Quantity > 0:
                return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = None
        if self.option.Symbol in slice.OptionChains:
            chain = slice.OptionChains[self.option.Symbol]

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        today = self.Time.date()
        contracts = list(chain.Contracts.Values)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug("Skipped entry: no future call expiration satisfies the rule.")
            return

        expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"(expiration {expiration}, strike {selected.Strike})"
        )

    def _process_option_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        expiration = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiration:
            self.no_entry_date = current_date
            self._submit_option_exit("expiration processing")
            return

        preceding_trading_day = self._preceding_trading_day(expiration)
        if (
            current_date == preceding_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.no_entry_date = current_date
            self._submit_option_exit("expiration time stop")
            return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_option_exit("50% profit target")

    def _submit_option_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            if reason == "50% profit target":
                self.exit_ticket.Cancel("Canceled in favor of profit-target liquidation.")
            else:
                return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol} ({reason})")

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        expiration = self.held_symbol.ID.Date.date()
        if self.Time.date() >= expiration:
            self.no_entry_date = self.Time.date()
            self._submit_option_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.no_entry_date = self.Time.date()
            self.Debug(
                f"Unexpected exercise or assignment handling: "
                f"liquidating {quantity} SPY shares."
            )
            self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise/assignment")

    def _preceding_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _ticket_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
                and order_event.FillQuantity > 0
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.time_stop_submitted = False
                self.Debug(
                    f"Entry filled: {self.held_symbol} "
                    f"at {self.entry_price}"
                )

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
                and order_event.FillQuantity < 0
            ):
                self.Debug(f"Exit filled: {order_event.Symbol}")
                if self.Portfolio[order_event.Symbol].Quantity <= 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.no_entry_date = self.Time.date()
            self.Debug(
                f"Unexpected exercise or assignment event for "
                f"{order_event.Symbol}; liquidating SPY immediately."
            )
            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -quantity,
                    tag="Unexpected exercise/assignment"
                )

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.entry_ticket = None if order_event.Status != OrderStatus.PartiallyFilled else self.entry_ticket

    def OnEndOfAlgorithm(self):
        if self.bucket_start is not None:
            self._complete_bucket(Slice())

