class SpyLongCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.bucket_start = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_tickets = []
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()
        self._process_option_exit(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_spy_minute(bar, slice)

    def _process_spy_minute(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time
        clock_time = local_time.time()

        if clock_time < time(9, 30) or clock_time >= time(16, 0):
            return

        minutes = (clock_time.hour - 9) * 60 + clock_time.minute - 30
        bucket_minutes = minutes // 5 * 5
        bucket_start = datetime(
            local_time.year,
            local_time.month,
            local_time.day,
            9,
            30,
        ) + timedelta(minutes=bucket_minutes)

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._complete_bucket(self.bucket_start, slice)

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[bar.Time] = bar

    def _complete_bucket(self, bucket_start: datetime, slice: Slice):
        bars = list(self.bucket_bars.values())
        self.bucket_start = None
        self.bucket_bars = {}

        if len(bars) != 5:
            return

        bars.sort(key=lambda item: item.Time)

        expected = bucket_start
        for bar in bars:
            if bar.Time != expected:
                return
            expected += timedelta(minutes=1)

        close = bars[-1].Close
        self.closes.append(float(close))

        if len(self.closes) > self.slow_period:
            self.closes = self.closes[-self.slow_period:]

        if len(self.closes) < self.slow_period:
            return

        fast_previous = sum(self.closes[-self.fast_period - 1:-1]) / self.fast_period
        slow_previous = sum(self.closes[-self.slow_period - 1:-1]) / self.slow_period
        fast_current = sum(self.closes[-self.fast_period:]) / self.fast_period
        slow_current = sum(self.closes[-self.slow_period:]) / self.slow_period

        crossover_end = bucket_start + timedelta(minutes=5)
        crossover_time = crossover_end.time()

        if not (
            fast_previous <= slow_previous
            and fast_current > slow_current
            and time(9, 45) <= crossover_time <= time(14, 30)
        ):
            return

        self._try_enter(slice, float(close))

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() > current_date
        })

        if not expirations:
            self.Debug("Skipped entry: no valid expiration.")
            return

