from collections import deque
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option = option

        self.closes = deque(maxlen=20)
        self.current_bucket_end = None
        self.current_bucket = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_date = None

        self.blocked_dates = set()

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position(current_date)
        self._process_expiration(current_date)

        if self.held_symbol is not None:
            self._evaluate_exit(slice, current_date)

        chain = self._get_option_chain(slice)
        self._process_spy_minute_bar(slice, chain)

    def _process_spy_minute_bar(self, slice: Slice, chain):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        local_time = self.Time
        minute = local_time.hour * 60 + local_time.minute

        # Regular session minute bars ending from 09:31 through 16:00.
        if minute < 9 * 60 + 31 or minute > 16 * 60:
            return

        # Five-minute buckets aligned so 09:31-09:35 ends at 09:35.
        bucket_end_minute = 9 * 60 + 35 + ((minute - (9 * 60 + 31)) // 5) * 5
        bucket_end = local_time.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.current_bucket = {}

        self.current_bucket[minute] = bar.Close

        expected_minutes = set(range(bucket_end_minute - 4, bucket_end_minute + 1))
        if minute != bucket_end_minute or set(self.current_bucket) != expected_minutes:
            return

        close = self.current_bucket[bucket_end_minute]
        self.current_bucket = {}

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        eligible_time = (
            bucket_end.hour > 9 or
            (bucket_end.hour == 9 and bucket_end.minute >= 45)
        ) and (
            bucket_end.hour < 14 or
            (bucket_end.hour == 14 and bucket_end.minute <= 30)
        )

        bullish_crossover = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_crossover and eligible_time:
            self._attempt_entry(chain, close, bucket_end.date())

    def _attempt_entry(self, chain, spy_price, signal_date):
        if signal_date in self.blocked_dates:
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > current_date
        ]

        if not calls:
            self.Debug("Skipped entry: no eligible expiration.")
            return

        # With no additional expiration constraint specified, use the
        # nearest future calendar expiration.
        expiration_date = min(contract.Expiry.date() for contract in calls)
        expiration_calls = [
            contract for contract in calls
            if contract.Expiry.date() == expiration_date
        ]

        minimum_strike = 1.01 * spy_price
        candidates = [
            contract for contract in expiration_calls
            if contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no call meets the strike rule.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.expiration_date = expiration_date
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiration {expiration_date}; strike {selected.Strike}"
        )

    def _evaluate_exit(self, slice, current_date):
        if self.held_symbol is None or self._exit_order_open():
            return

        if self.expiration_date is not None:
            previous_trading_day = self._previous_trading_day(
                self.expiration_date
            )

            if (
                current_date == previous_trading_day and
                self.Time.hour * 60 + self.Time.minute >= 15 * 60 + 45
            ):
                self._submit_exit("expiration time stop")
                return

        contract = self._get_held_contract(slice)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if (
            self.entry_price is not None and
            bid is not None and
            ask is not None and
            bid > 0 and
            ask > 0
        ):
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("50% profit target")

    def _process_expiration(self, current_date):
        if self.expiration_date is None:
            return

        if current_date >= self.expiration_date:
            self.blocked_dates.add(current_date)

            if self._entry_order_open() and self.entry_ticket is not None:
                self.entry_ticket.Cancel("expiration processing")
                self.entry_ticket = None
                self.entry_symbol = None

            if self.held_symbol is not None and not self._exit_order_open():
                self._submit_exit("expiration liquidation")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_open():
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("replaced by liquidation")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol}; {reason}")

    def _handle_unexpected_spy_position(self, current_date):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.blocked_dates.add(current_date)
        self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
        self.MarketOrder(self.spy, -quantity, tag="unexpected exercise/assignment")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = (
                    self.Securities[order_event.Symbol].Symbol.ID.Date.date()
                )
                self.Debug(
                    f"Entry filled: {self.held_symbol}; "
                    f"price {self.entry_price}"
                )
                self.entry_ticket = None
                self.entry_symbol = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_symbol = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _get_option_chain(self, slice):
        if self.option.Symbol not in slice.OptionChains:
            return None
        return slice.OptionChains[self.option.Symbol]

    def _get_held_contract(self, slice):
        chain = self._get_option_chain(slice)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == self.held_symbol:
                return contract

        return None

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _previous_trading_day(self, date):
        previous = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(previous):
            previous -= timedelta(days=1)

        return previous

