from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda u: u.IncludeWeeklys()
                      .Strikes(-1000, 1000)
                      .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.minute_buckets = {}
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_fill_price = None
        self.expiration_block_date = None
        self.equity_cleanup_ticket = None

    def OnData(self, data: Slice):
        today = self.Time.date()

        self._handle_unexpected_equity_position()
        self._process_expiration(today)

        if self.held_option is not None:
            self._evaluate_option_exit(data, today)

        bar = data.Bars[self.spy] if self.spy in data.Bars else None
        if bar is not None:
            self._process_minute_bar(bar, data)

    def _process_minute_bar(self, minute_bar, data):
        end_time = minute_bar.EndTime
        local_end = end_time.astimezone(self.TimeZone).replace(tzinfo=None)

        if local_end.weekday() >= 5:
            return

        if not (
            local_end.time() >= datetime.strptime("09:30", "%H:%M").time()
            and local_end.time() <= datetime.strptime("16:00", "%H:%M").time()
        ):
            return

        bucket_minute = ((local_end.minute + 4) // 5) * 5
        bucket_end = local_end.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=bucket_minute)

        bucket = self.minute_buckets.setdefault(bucket_end, {})
        bucket[local_end] = minute_bar

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if local_end != bucket_end or not all(
            expected_time in bucket for expected_time in expected_times
        ):
            return

        bars = [bucket[t] for t in expected_times]
        del self.minute_buckets[bucket_end]

        consolidated = TradeBar(
            bucket_end - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

        self._process_five_minute_bar(consolidated, data)

    def _process_five_minute_bar(self, bar, data):
        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

        values = list(self.closes)
        fast_current = sum(values[-self.fast_period:]) / self.fast_period
        slow_current = sum(values[-self.slow_period:]) / self.slow_period

        if len(values) < self.slow_period + 1:
            return

        previous_values = values[:-1]
        fast_previous = (
            sum(previous_values[-self.fast_period:]) / self.fast_period
        )
        slow_previous = (
            sum(previous_values[-self.slow_period:]) / self.slow_period
        )

        bullish_crossover = (
            fast_previous <= slow_previous
            and fast_current > slow_current
        )

        bar_end = bar.EndTime.astimezone(self.TimeZone).replace(tzinfo=None)
        eligible_time = (
            datetime.strptime("09:45", "%H:%M").time()
            <= bar_end.time()
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        if bullish_crossover and eligible_time:
            self._try_enter(data, float(bar.Close), bar_end.date())

    def _try_enter(self, data, spy_price, signal_date):
        if self.expiration_block_date == signal_date:
            return

        if self.held_option is not None:
            return

        if self._order_is_open(self.entry_ticket):
            return

        if not data.OptionChains or self.option_symbol not in data.OptionChains:
            self.Debug("Skipped selection: no option chain.")
            return

        chain = data.OptionChains[self.option_symbol]
        future_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() > signal_date
        })

        if not future_expirations:
            self.Debug("Skipped selection: no valid expiration.")
            return

        selected_expiration = future_expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        candidates.sort(
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected_expiration,
                selected.Strike
            )
        )

    def _evaluate_option_exit(self, data, today):
        symbol = self.held_option
        holding = self.Portfolio[symbol]

        if holding.Quantity <= 0:
            self.held_option = None
            self.entry_fill_price = None
            return

        expiration_date = symbol.ID.Date.date()

        if today >= expiration_date:
            self.expiration_block_date = today
            self._submit_option_exit(
                "Expiration-day liquidation"
            )
            return

        previous_trading_day = self._previous_trading_day(expiration_date)
        local_time = self.Time.time()

        if (
            today == previous_trading_day
            and local_time >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self._submit_option_exit(
                "Expiration-eve time stop"
            )
            return

        if not data.OptionChains or self.option_symbol not in data.OptionChains:
            return

        current_contract = None
        for contract in data.OptionChains[self.option_symbol]:
            if contract.Symbol == symbol:
                current_contract = contract
                break

        if current_contract is None:
            return

        bid = float(current_contract.BidPrice)
        ask = float(current_contract.AskPrice)

        if (
            self.entry_fill_price is not None
            and bid > 0
            and ask > 0
        ):
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.50 * self.entry_fill_price:
                self._submit_option_exit("50 percent profit target")

    def _submit_option_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel()

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0} ({1})".format(
                self.held_option,
                reason
            )
        )

    def _process_expiration(self, today):
        if self.held_option is None:
            return

        expiration_date = self.held_option.ID.Date.date()
        if today >= expiration_date:
            self.expiration_block_date = today
            self._submit_option_exit("Expiration processing liquidation")

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if not self._order_is_open(self.equity_cleanup_ticket):
            self.Debug(
                "Unexpected exercise or assignment: liquidating SPY equity."
            )
            self.equity_cleanup_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment cleanup"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.held_option = order_event.Symbol
            self.entry_fill_price = float(order_event.FillPrice)
            self.entry_ticket = None
            self.Debug(
                "Entry filled: {0}, price {1}".format(
                    self.held_option,
                    self.entry_fill_price
                )
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {0}, price {1}".format(
                    order_event.Symbol,
                    order_event.FillPrice
                )
            )
            self.exit_ticket = None
            if self.Portfolio[order_event.Symbol].Quantity == 0:
                self.held_option = None
                self.entry_fill_price = None

        if (
            order_event.Status == OrderStatus.Filled
            and order_event.Symbol.SecurityType == SecurityType.Option
            and getattr(order_event, "IsAssignment", False)
        ):
            self.Debug(
                "Unexpected exercise or assignment event: {0}".format(
                    order_event.Symbol
                )
            )
            self._handle_unexpected_equity_position()

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _order_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

