from datetime import datetime, timedelta, time


class SpyLongCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fill_forward=False,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.bar_end = None
        self.minute_bars = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_expiry = None
        self.entry_price = None

        self.exit_ticket = None
        self.no_entry_today = False
        self.last_expiration_check_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(today)
        self._evaluate_open_position_exit(slice, today)

        if self.IsWarmingUp or self.no_entry_today:
            return

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        if end_time.date() != self.Time.date():
            return

        session_start = time(9, 30)
        session_end = time(16, 0)

        if end_time.time() <= session_start or end_time.time() > session_end:
            return

        minute = end_time.replace(second=0, microsecond=0)
        bucket_end_minute = minute.minute + ((5 - minute.minute % 5) % 5)
        bucket_end = minute.replace(minute=0) + timedelta(minutes=bucket_end_minute)

        if self.bar_end != bucket_end:
            self.bar_end = bucket_end
            self.minute_bars = {}

        self.minute_bars[minute] = bar

        if minute != bucket_end:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(expected not in self.minute_bars for expected in expected_times):
            self.minute_bars = {}
            return

        bars = [self.minute_bars[expected] for expected in expected_times]
        close = bars[-1].Close

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bucket_end, close)
        self.slow.Update(bucket_end, close)

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        eligible_time = time(9, 45) <= bucket_end.time() <= time(14, 30)
        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        if eligible_time and bullish_crossover:
            self._try_enter(slice, close)

        self.minute_bars = {}

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.no_entry_today:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        if self.entry_symbol is not None:
            holding = self.Portfolio[self.entry_symbol]
            if holding.Invested or holding.Quantity != 0:
                return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        current_date = self.Time.date()
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() > current_date
        })

        if not expiries:
            self.Debug(f"{self.Time}: skipped entry; no valid expiration")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no qualifying call")
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_expiry = selected.Expiry.date()
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)

        self.Debug(
            f"{self.Time}: entry submitted {self.entry_symbol}, "
            f"expiry={self.entry_expiry}, strike={selected.Strike}"
        )

    def _evaluate_open_position_exit(self, slice: Slice, today):
        if self.entry_symbol is None or self.entry_expiry is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested or holding.Quantity <= 0:
            return

        if self._order_is_open(self.exit_ticket):
            return

        time_stop_date = self._previous_trading_day(self.entry_expiry)
        time_stop = (
            today == time_stop_date
            and self.Time.time() >= time(15, 45)
        )

        target = False
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None and self.entry_price is not None:
            contract = next(
                (c for c in chain if c.Symbol == self.entry_symbol),
                None
            )

            if contract is not None:
                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    target = midpoint >= 1.50 * self.entry_price

        if target or time_stop:
            reason = "profit target" if target else "expiration time stop"
            self._submit_exit(reason, holding.Quantity)

    def _submit_exit(self, reason: str, quantity: int):
        if self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(self.entry_symbol, -quantity)
        self.Debug(f"{self.Time}: exit submitted ({reason}) {self.entry_symbol}")

    def _handle_expiration_processing(self, today):
        if self.last_expiration_check_date == today:
            return

        self.last_expiration_check_date = today

        if self.entry_expiry is not None and today >= self.entry_expiry:
            self.no_entry_today = True

            if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
                self.entry_ticket.Cancel("Expiration processing")

            holding = self.Portfolio[self.entry_symbol]
            if holding.Quantity != 0 and not self._order_is_open(self.exit_ticket):
                self._submit_exit("expiration processing", holding.Quantity)

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(
                f"{self.Time}: unexpected exercise or assignment; "
                f"liquidating SPY position of {quantity}"
            )
            if not self._order_is_open(self.exit_ticket):
                self.MarketOrder(self.spy, -quantity)
            self.no_entry_today = True

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(f"{self.Time}: unexpected option exercise or assignment")
        self.no_entry_today = True

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                if self.entry_price is None:
                    self.entry_price = float(order_event.FillPrice)

                self.Debug(
                    f"{self.Time}: entry filled {self.entry_symbol} "
                    f"at {self.entry_price}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                if order_event.Status != OrderStatus.None_:
                    self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: exit filled {self.entry_symbol}")
                self.exit_ticket = None
                self.entry_symbol = None
                self.entry_expiry = None
                self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

