                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False
        self.pending_signal_time = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            local_time = bar.EndTime
            if local_time.hour >= 9 and local_time.hour <= 14:
                if (
                    (local_time.hour > 9 or local_time.minute >= 45)
                    and (local_time.hour < 14 or local_time.minute <= 30)
                ):
                    self.pending_signal = True
                    self.pending_signal_time = local_time

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

    def OnData(self, slice):
        current_date = self.Time.date()

        if self.held_symbol is not None:
            if self.expiration_date is not None and current_date >= self.expiration_date:
                self.no_entry_date = current_date
                self.SubmitExit("expiration processing")
            elif self.IsTimeStopDue():
                self.SubmitExit("time stop")
            else:
                self.CheckProfitTarget(slice)

        if (
            self.pending_signal
            and self.pending_signal_time is not None
            and self.pending_signal_time.date() == current_date
        ):
            self.pending_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None:
            return

        if self.held_symbol is not None:
            return

        option_chain = slice.OptionChains.get(self.option_symbol)
        if option_chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        current_date = self.Time.date()
        future_expirations = sorted({
            contract.Expiry.date()
            for contract in option_chain
            if contract.Expiry.date() > current_date
        })

        if not future_expirations:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        expiration = future_expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in option_chain
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.Debug(
            f"Call entry submitted: {selected.Symbol}, "
            f"expiration {expiration.isoformat()}"
        )

    def CheckProfitTarget(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_order_id is not None:
            return

        option_chain = slice.OptionChains.get(self.option_symbol)
        if option_chain is None:
            return

        held_contract = next(
            (contract for contract in option_chain
             if contract.Symbol == self.held_symbol),
            None
        )

        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def IsTimeStopDue(self):
        if self.expiration_date is None:
            return False

        previous_trading_day = self.expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        return (
            self.Time.date() == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        )

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if reason == "50% profit target":
            for ticket in self.Transactions.GetOpenOrders(self.held_symbol):
                if ticket.OrderId != self.entry_order_id:
                    self.Transactions.CancelOrder(
                        ticket.OrderId,
                        "Profit target reached; canceling other exit."
                    )

        self.exit_order_id = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        ).OrderId
        self.Debug(f"Call exit submitted: {reason}")

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if order_event.OrderId == self.entry_order_id:
                self.entry_order_id = None
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = order_event.Symbol.ID.Date.date()
                self.Debug(
                    f"Call entry filled: {self.held_symbol}, "
                    f"price {self.entry_price}"
                )

            elif order_event.OrderId == self.exit_order_id:
                self.exit_order_id = None
                self.Debug(
                    f"Call exit filled: {order_event.Symbol}, "
                    f"price {order_event.FillPrice}"
                )

                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiration_date = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None_
        ):
            if order_event.OrderId == self.entry_order_id:
                self.entry_order_id = None
            elif order_event.OrderId == self.exit_order_id:
                self.exit_order_id = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                f"Unexpected exercise or assignment: {order_event.Symbol}"
            )
            equity_quantity = self.Portfolio[self.spy].Quantity
            if equity_quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -equity_quantity,
                    tag="Unexpected exercise or assignment"
                )
                self.Debug("Liquidating SPY equity from exercise or assignment.")

