                self.bar_data = None
                self.bar_expected_minute = None
                return

            self.bar_data = {
                "open": minute_bar.Open,
                "high": minute_bar.High,
                "low": minute_bar.Low,
                "close": minute_bar.Close,
                "volume": minute_bar.Volume,
                "count": 1,
            }
            self.bar_expected_minute = minute + 1
        else:
            self.bar_data["high"] = max(self.bar_data["high"], minute_bar.High)
            self.bar_data["low"] = min(self.bar_data["low"], minute_bar.Low)
            self.bar_data["close"] = minute_bar.Close
            self.bar_data["volume"] += minute_bar.Volume
            self.bar_data["count"] += 1
            self.bar_expected_minute += 1

        if self.bar_data is None or self.bar_data["count"] != 5:
