        current_slow = sum(self.slow_closes) / 20.0 if len(self.slow_closes) == 20 else None

        self.bar_data = None
        self.bar_expected_minute = None

        if (
            previous_fast is not None
            and previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
            and self._time(9, 45) <= completed_bar_end.time() <= self._time(14, 30)
