        if self.blocked_entry_date == signal_date:
            return

        if self._has_open_entry_order() or self._has_open_exit_order():
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_price = self.Securities[self.spy].Price
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        current_date = self.Time.date()
        eligible = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiry = contract.Expiry.date()
                dte = (expiry - current_date).days

                if (
                    dte >= 1
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= 1.01 * current_price
                ):
                    eligible.append(contract)

        if not eligible:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible)
        candidates = [
            contract
            for contract in eligible
            if contract.Expiry.date() == selected_expiry
        ]

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY call entry",
        )
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _evaluate_exit(self, slice: Slice, current_date):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        expiry_date = self.held_option.ID.Date.date()

        if (
            current_date == self._previous_trading_day(expiry_date)
            and self.Time.time() >= self._time(15, 45)
        ):
            self._submit_exit("Expiration time stop")
            return

        contract = self._get_current_contract(slice, self.held_option)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0 or self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self._has_open_exit_order():
            return

        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason,
        )
        self.Debug("Exit submitted: " + reason)

    def _process_expiration(self, current_date):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if current_date >= expiry_date:
            self.blocked_entry_date = current_date
            self._submit_exit("Expiration protection")
            self.Debug("Expiration protection triggered.")

    def _handle_unexpected_equity_position(self, current_date):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.blocked_entry_date = current_date
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation",
            )
            self.Debug("Unexpected exercise or assignment handled.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.entry_price = order_event.FillPrice
                self.held_option = order_event.Symbol
                self.Debug(
                    "Entry filled: "
                    + str(order_event.Symbol)
                    + " at "
                    + str(order_event.FillPrice)
                )

            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.FillQuantity != 0:
                self.Debug("Exit filled: " + str(order_event.Symbol))

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = None
                    self.entry_price = None
                self.exit_ticket = None

    def _get_current_contract(self, slice: Slice, symbol):
        for chain in slice.OptionChains.Values:
            if symbol in chain.Contracts:
                return chain.Contracts[symbol]
        return None

    def _has_open_entry_order(self):
        if self.entry_ticket is None:
            return False
        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        )

    def _has_open_exit_order(self):
        if self.exit_ticket is None:
            return False
        return self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    @staticmethod
    def _time(hour, minute):
        from datetime import time
        return time(hour, minute)

