            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_date = None

        self.pending_signal_time = None
        self.no_entry_date = None
        self.equity_liquidation_ticket = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = bar.EndTime.time()

        if bar_time < time(9, 35) or bar_time > time(16, 0):
            return

        prior_fast = None
        prior_slow = None

        if len(self.fast_values) == 5:
            prior_fast = sum(self.fast_values) / 5.0
        if len(self.slow_values) == 20:
            prior_slow = sum(self.slow_values) / 20.0

        self.fast_values.append(float(bar.Close))
        self.slow_values.append(float(bar.Close))

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        current_fast = sum(self.fast_values) / 5.0
        current_slow = sum(self.slow_values) / 20.0

        bullish_cross = (
            prior_fast is not None and
            prior_slow is not None and
            prior_fast <= prior_slow and
            current_fast > current_slow
        )

        if (
            bullish_cross and
            time(9, 45) <= bar_time <= time(14, 30)
        ):
            self.pending_signal_time = bar.EndTime

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def OnData(self, slice):
        self._liquidate_unexpected_equity_position()

        if self.entry_symbol is not None:
            current_date = self.Time.date()

            if (
                self.expiration_date is not None and
                current_date >= self.expiration_date
            ):
                self.no_entry_date = current_date
                self._submit_exit("expiration processing")
            elif (
                self.expiration_date is not None and
                self.Time.time() >= time(15, 45) and
                self._is_trading_day_before_expiration(
                    current_date,
                    self.expiration_date
                )
            ):
                self._submit_exit("pre-expiration time stop")
            else:
                self._evaluate_profit_target(slice)

        if self.pending_signal_time is not None:
            signal_date = self.pending_signal_time.date()
            self.pending_signal_time = None

            if signal_date == self.Time.date():
                self._evaluate_entry(slice)

