        if self.no_entry_date == self.Time.date():
            return

        if self.entry_ticket is not None:
            return

        if self.entry_symbol is not None:
            return

        chain = None
        for canonical_symbol, option_chain in slice.OptionChains.items():
            if canonical_symbol == self.option.Symbol:
                chain = option_chain
                break

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
