from AlgorithmImports import *
from datetime import datetime, timedelta
from collections import deque


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.fast_sum = 0.0
        self.slow_sum = 0.0

        self.current_bucket_start = None
        self.current_bucket_bars = {}

        self.held_option = None
        self.entry_order = None
        self.entry_price = None
        self.exit_order = None
        self.no_entry_date = None
        self.equity_liquidation_submitted = False

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        current_date = self.Time.date()
        new_bar = self._update_five_minute_bar(slice)

        if self.held_option is not None:
            self._process_option_exit(slice)

        if (
            new_bar is not None
            and current_date != self.no_entry_date
            and self.held_option is None
            and not self._entry_order_is_open()
        ):
            self._evaluate_entry(slice, new_bar)

    def _update_five_minute_bar(self, slice: Slice):
        if not slice.Bars.ContainsKey(self.spy):
            return None

        minute_bar = slice.Bars[self.spy]
        end_time = minute_bar.EndTime.replace(second=0, microsecond=0)
        start_time = end_time - timedelta(minutes=1)

        session_start = datetime(
            start_time.year, start_time.month, start_time.day, 9, 30
        )
        session_end = datetime(
            start_time.year, start_time.month, start_time.day, 16, 0
        )

        if start_time < session_start or start_time >= session_end:
            return None

        elapsed_minutes = int((start_time - session_start).total_seconds() // 60)
        bucket_offset = elapsed_minutes // 5
        bucket_start = session_start + timedelta(minutes=bucket_offset * 5)

        if (
            self.current_bucket_start is not None
            and bucket_start != self.current_bucket_start
        ):
            self._discard_incomplete_bucket()

        if self.current_bucket_start != bucket_start:
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = {}

        self.current_bucket_bars[start_time] = minute_bar.Close

        bucket_end = bucket_start + timedelta(minutes=5)
        if end_time != bucket_end:
            return None

        expected_times = {
            bucket_start + timedelta(minutes=i) for i in range(5)
        }

        if set(self.current_bucket_bars.keys()) != expected_times:
            self.current_bucket_bars = {}
            self.current_bucket_start = None
            return None

        consolidated_close = minute_bar.Close
        self.current_bucket_bars = {}
        self.current_bucket_start = None

        self.slow_values.append(consolidated_close)
        self.slow_sum += consolidated_close

        if len(self.slow_values) == self.slow_values.maxlen:
            self.slow_sum -= self.slow_values[0]

        if len(self.fast_values) == self.fast_values.maxlen:
            self.fast_sum -= self.fast_values[0]

        self.fast_values.append(consolidated_close)
        self.fast_sum += consolidated_close

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return None

        fast_average = self.fast_sum / 5.0
        slow_average = self.slow_sum / 20.0

        previous_fast = getattr(self, "previous_fast_average", None)
        previous_slow = getattr(self, "previous_slow_average", None)

        self.previous_fast_average = fast_average
        self.previous_slow_average = slow_average

        if previous_fast is None or previous_slow is None:
            return None

        return {
            "end_time": bucket_end,
            "fast": fast_average,
            "slow": slow_average,
            "previous_fast": previous_fast,
            "previous_slow": previous_slow,
        }

    def _discard_incomplete_bucket(self):
        self.current_bucket_bars = {}
        self.current_bucket_start = None

    def _evaluate_entry(self, slice: Slice, bar_info):
        bar_end = bar_info["end_time"]
        eligible_start = bar_end.replace(hour=9, minute=45)
        eligible_end = bar_end.replace(hour=14, minute=30)

        if not (eligible_start <= bar_end <= eligible_end):
            return

        bullish_cross = (
            bar_info["previous_fast"] <= bar_info["previous_slow"]
            and bar_info["fast"] > bar_info["slow"]
        )

        if not bullish_cross:
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_price = self.Securities[self.spy].Price

        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug("Skipped entry: no valid expiration.")
            return

        # Select the nearest future expiration by calendar date.
        selected_expiration = expirations[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call.")
            return

        selected_contract = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_order = self.MarketOrder(
            selected_contract.Symbol,
            1,
            False,
            "SPY bullish crossover entry"
        )

    def _process_option_exit(self, slice: Slice):
        symbol = self.held_option
        if symbol is None:
            return

        expiration_date = symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiration_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration liquidation")
            return

        if (
            self.Time.hour == 15
            and self.Time.minute >= 45
            and self._is_trading_day_immediately_before(
                current_date, expiration_date
            )
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            return

        chain = slice.OptionChains[self.option_symbol]
        contract = next(
            (item for item in chain if item.Symbol == symbol),
            None
        )

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self._exit_order_is_open():
            return

        if self.exit_order is not None:
            self.exit_order.Cancel("Replacing existing exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_order = self.MarketOrder(
            self.held_option,
            -quantity,
            False,
            reason
        )

    def _entry_order_is_open(self):
        if self.entry_order is None:
            return False

        return self.entry_order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_is_open(self):
        if self.exit_order is None:
            return False

        return self.exit_order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _is_trading_day_immediately_before(self, current_date, expiration_date):
        candidate = current_date + timedelta(days=1)

        while candidate < expiration_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
                return False
            candidate += timedelta(days=1)

        return candidate == expiration_date

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            if not self.equity_liquidation_submitted:
                self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
                self.MarketOrder(
                    self.spy,
                    -quantity,
                    False,
                    "Unexpected exercise or assignment handling"
                )
                self.equity_liquidation_submitted = True
        else:
            self.equity_liquidation_submitted = False

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order is not None
            and order_event.OrderId == self.entry_order.OrderId
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ) and order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_option} at {self.entry_price:.4f}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                if order_event.Status != OrderStatus.Filled:
                    self.Debug("Skipped entry: entry order did not fill.")
                self.entry_order = None

        if (
            self.exit_order is not None
            and order_event.OrderId == self.exit_order.OrderId
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ):
                self.Debug(
                    f"Exit submitted/filled: {order_event.Symbol}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                if (
                    self.held_option is not None
                    and self.Portfolio[self.held_option].Quantity == 0
                ):
                    self.held_option = None
                    self.entry_price = None
                    self.exit_order = None

        if order_event.Symbol == self.spy:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ) and order_event.FillQuantity != 0:
                self.Debug(
                    "Unexpected SPY exercise or assignment event; liquidating equity."
                )
                quantity = self.Portfolio[self.spy].Quantity
                if quantity != 0:
                    self.MarketOrder(
                        self.spy,
                        -quantity,
                        False,
                        "Unexpected exercise or assignment handling"
                    )

