from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.current_bucket = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.no_entry_date = None
        self.expiration_guard_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_date = today
                self._liquidate_option("expiration guard")
            elif self._is_time_stop_day(expiry_date, today) and self.Time.time() >= time(15, 45):
                self._liquidate_option("expiration time stop")
            else:
                self._check_profit_target(slice)

        if self._has_open_entry_order():
            return

        if self.held_symbol is not None:
            return

        if self.no_entry_date == today:
            return

        if getattr(self, "_pending_signal", False):
            self._pending_signal = False
            self._try_enter(slice)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {self.held_symbol.Value}, "
                    f"price={self.entry_price:.4f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Expired
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Expired
            ):
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(f"Exit filled: {self.held_symbol.Value}")
                    if self.Portfolio[self.held_symbol].Quantity == 0:
                        self.held_symbol = None
                        self.entry_price = None
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self._handle_unexpected_assignment()

    def OnAssignmentOrder(self, assignment_order):
        self.Debug("Unexpected option exercise or assignment detected.")
        self._liquidate_spy_equity()

    def _process_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        local_end = end_time.astimezone(self.TimeZone) if end_time.tzinfo else end_time

        if local_end.time() < time(9, 31) or local_end.time() > time(16, 0):
            self.current_bucket = None
            self.bucket_bars = {}
            return

        minute = local_end.minute
        bucket_end_minute = ((minute - 1) // 5 + 1) * 5
        bucket_end = local_end.replace(
            minute=bucket_end_minute,
            second=0,
            microsecond=0
        )
        bucket_key = bucket_end

        if self.current_bucket is not None and bucket_key != self.current_bucket:
            self._finalize_bucket(self.current_bucket)

        if self.current_bucket != bucket_key:
            self.current_bucket = bucket_key
            self.bucket_bars = {}

        self.bucket_bars[local_end.minute] = bar

        if local_end.minute == bucket_end_minute:
            self._finalize_bucket(bucket_key)
            self.current_bucket = None
            self.bucket_bars = {}

    def _finalize_bucket(self, bucket_end):
        if bucket_end.time() < time(9, 35) or bucket_end.time() > time(16, 0):
            return

        expected_minutes = [
            bucket_end.minute - 4,
            bucket_end.minute - 3,
            bucket_end.minute - 2,
            bucket_end.minute - 1,
            bucket_end.minute
        ]

        if any(minute not in self.bucket_bars for minute in expected_minutes):
            return

        bars = [self.bucket_bars[minute] for minute in expected_minutes]
        close = bars[-1].Close

        self.closes.append(close)
        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period + 1:
            return

        previous = self.closes[:-1]
        current = self.closes

        previous_fast = sum(previous[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous[-self.slow_period:]) / self.slow_period
        current_fast = sum(current[-self.fast_period:]) / self.fast_period
        current_slow = sum(current[-self.slow_period:]) / self.slow_period

        if (
            previous_fast <= previous_slow
            and current_fast > current_slow
            and time(9, 45) <= bucket_end.time() <= time(14, 30)
        ):
            self._pending_signal = True

    def _try_enter(self, slice: Slice):
        if self.held_symbol is not None or self._has_open_entry_order():
            return

        chains = getattr(slice, "OptionChains", None)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        contracts = []
        for chain in chains:
            for contract in chain:
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: option chain contained no contracts.")
            return

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug("Skipped entry: no valid future expiration.")
            return

        expiration = expirations[0]
        spy_price = self.Securities[self.spy_symbol].Price

        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not eligible:
            self.Debug("Skipped entry: no call met the strike requirement.")
            return

        selected = sorted(
            eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"strike={selected.Strike:.2f}, expiration={expiration}"
        )

    def _check_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            return

        contract = None
        chains = getattr(slice, "OptionChains", None)
        if chains:
            for chain in chains:
                for candidate in chain:
                    if candidate.Symbol == self.held_symbol:
                        contract = candidate
                        break
                if contract is not None:
                    break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            self.held_symbol = None
            self.entry_price = None
            return

        if self.exit_ticket is not None:
            try:
                self.exit_ticket.Cancel(f"Replacing exit order: {reason}")
            except Exception:
                pass
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def _has_open_entry_order(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Expired
        )

    def _is_time_stop_day(self, expiration_date, current_date):
        candidate = expiration_date - timedelta(days=1)

        while candidate >= current_date - timedelta(days=7):
            if self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
                datetime(candidate.year, candidate.month, candidate.day)
            ):
                return current_date == candidate
            candidate -= timedelta(days=1)

        return False

    def _handle_unexpected_assignment(self):
        self.Debug("Handling unexpected exercise or assignment.")
        self._liquidate_spy_equity()

    def _liquidate_spy_equity(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity != 0:
            self.Debug(f"Liquidating unexpected SPY equity position: {quantity}")
            self.MarketOrder(self.spy_symbol, -quantity)

    def OnEndOfAlgorithm(self):
        if self.held_symbol is not None:
            self._liquidate_option("end of algorithm")

    def OnDataConsolidated(self, sender, consolidated):
        pass

    def OnSecuritiesChanged(self, changes):
        pass

    def OnData(self, slice: Slice):
        bar = slice.Bars.get(self.spy_symbol)
        if bar is not None:
            self._process_minute_bar(bar)

        today = self.Time.date()

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_date = today
                self._liquidate_option("expiration guard")
            elif self._is_time_stop_day(expiry_date, today) and self.Time.time() >= time(15, 45):
                self._liquidate_option("expiration time stop")
            else:
                self._check_profit_target(slice)

        if self._has_open_entry_order():
            return

        if self.held_symbol is not None:
            return

        if self.no_entry_date == today:
            return

        if getattr(self, "_pending_signal", False):
            self._pending_signal = False
            self._try_enter(slice)

