        self._liquidate_spy_equity()

    def _process_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        local_end = end_time.astimezone(self.TimeZone) if end_time.tzinfo else end_time

        if local_end.time() < time(9, 31) or local_end.time() > time(16, 0):
            self.current_bucket = None
            self.bucket_bars = {}
            return

        minute = local_end.minute
        bucket_end_minute = ((minute - 1) // 5 + 1) * 5
        bucket_end = local_end.replace(
            minute=bucket_end_minute,
            second=0,
            microsecond=0
        )
        bucket_key = bucket_end

        if self.current_bucket is not None and bucket_key != self.current_bucket:
            self._finalize_bucket(self.current_bucket)

        if self.current_bucket != bucket_key:
            self.current_bucket = bucket_key
            self.bucket_bars = {}

        self.bucket_bars[local_end.minute] = bar

        if local_end.minute == bucket_end_minute:
            self._finalize_bucket(bucket_key)
            self.current_bucket = None
            self.bucket_bars = {}

    def _finalize_bucket(self, bucket_end):
        if bucket_end.time() < time(9, 35) or bucket_end.time() > time(16, 0):
            return

        expected_minutes = [
            bucket_end.minute - 4,
            bucket_end.minute - 3,
            bucket_end.minute - 2,
            bucket_end.minute - 1,
            bucket_end.minute
        ]

        if any(minute not in self.bucket_bars for minute in expected_minutes):
            return

        bars = [self.bucket_bars[minute] for minute in expected_minutes]
        close = bars[-1].Close

        self.closes.append(close)
        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period + 1:
            return

        previous = self.closes[:-1]
        current = self.closes

        previous_fast = sum(previous[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous[-self.slow_period:]) / self.slow_period
        current_fast = sum(current[-self.fast_period:]) / self.fast_period
        current_slow = sum(current[-self.slow_period:]) / self.slow_period

        if (
            previous_fast <= previous_slow
            and current_fast > current_slow
            and time(9, 45) <= bucket_end.time() <= time(14, 30)
        ):
            self._pending_signal = True

    def _try_enter(self, slice: Slice):
        if self.held_symbol is not None or self._has_open_entry_order():
            return

        chains = getattr(slice, "OptionChains", None)
        if not chains:
