        self._liquidate_spy_equity()

    def _liquidate_spy_equity(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity != 0:
            self.Debug(f"Liquidating unexpected SPY equity position: {quantity}")
            self.MarketOrder(self.spy_symbol, -quantity)

    def OnEndOfAlgorithm(self):
        if self.held_symbol is not None:
            self._liquidate_option("end of algorithm")

    def OnDataConsolidated(self, sender, consolidated):
        pass

    def OnSecuritiesChanged(self, changes):
        pass

    def OnData(self, slice: Slice):
        bar = slice.Bars.get(self.spy_symbol)
        if bar is not None:
            self._process_minute_bar(bar)

        today = self.Time.date()

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_date = today
                self._liquidate_option("expiration guard")
            elif self._is_time_stop_day(expiry_date, today) and self.Time.time() >= time(15, 45):
