            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False,
            leverage=1,
            extendedMarketHours=False
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._minute_bars = {}
        self._previous_fast = None
        self._previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY exercise or assignment detected; liquidating equity.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
            self.blocked_entry_date = current_date

        self._process_expiration()
        self._process_option_exit(slice)

        spy_bar = slice.Bars.get(self.spy)
        bullish_crossover = False
        crossover_end = None

        if spy_bar is not None:
            consolidated = self._consolidate_minute_bar(spy_bar)

            if consolidated is not None:
                bar_end, close = consolidated

                previous_fast = float(self.fast.Current.Value) if self.fast.IsReady else None
                previous_slow = float(self.slow.Current.Value) if self.slow.IsReady else None

                self.fast.Update(IndicatorDataPoint(bar_end, close))
                self.slow.Update(IndicatorDataPoint(bar_end, close))

                if self.fast.IsReady and self.slow.IsReady:
                    bullish_crossover = (
                        previous_fast is not None and
                        previous_slow is not None and
                        previous_fast <= previous_slow and
                        float(self.fast.Current.Value) > float(self.slow.Current.Value)
                    )
                    crossover_end = bar_end

        if not bullish_crossover:
            return

        if not (time(9, 45) <= crossover_end.time() <= time(14, 30)):
            return

        if (
            self.blocked_entry_date == current_date or
            self.held_symbol is not None or
            self._entry_order_open()
        ):
            return

        self._enter_from_current_chain(slice, float(spy_bar.Close))

    def _consolidate_minute_bar(self, minute_bar):
        end = minute_bar.EndTime
        session_start = datetime.combine(end.date(), time(9, 30))
        session_end = datetime.combine(end.date(), time(16, 0))

        if end <= session_start or end > session_end:
            return None

        minutes_from_start = int((end - session_start).total_seconds() // 60)
        bucket_end = session_start + timedelta(
            minutes=((minutes_from_start // 5) + 1) * 5
        )

        bucket = self._minute_bars.setdefault(bucket_end, {})
        bucket[end] = minute_bar

        if end != bucket_end:
            return None

        expected_times = [
            bucket_end - timedelta(minutes=i) for i in range(1, 6)
        ]

        if any(expected_time not in bucket for expected_time in expected_times):
            del self._minute_bars[bucket_end]
            return None

        bars = [bucket[expected_time] for expected_time in reversed(expected_times)]
        del self._minute_bars[bucket_end]

        close = bars[-1].Close
        return bucket_end, close

    def _enter_from_current_chain(self, slice, spy_price):
        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        today = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and
            (contract.Expiry.date() - today).days >= self.TARGET_DTE
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        expiration = min(
            expirations,
            key=lambda expiry: (
                (expiry - today).days - self.TARGET_DTE,
                expiry
            )
        )

        minimum_strike = spy_price * 1.01
        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call and
            contract.Expiry.date() == expiration and
            float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiration {expiration}, "
            f"strike {selected.Strike}"
        )

    def _process_option_exit(self, slice):
        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        contract = None
        if self.option_symbol in slice.OptionChains:
            for candidate in slice.OptionChains[self.option_symbol]:
                if candidate.Symbol == self.held_symbol:
                    contract = candidate
                    break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("profit target", quantity)

    def _process_expiration(self):
        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        security = self.Securities[self.held_symbol]
        expiration = security.Symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiration:
            self.blocked_entry_date = today
            self._submit_exit("expiration processing", self.Portfolio[self.held_symbol].Quantity)
            return

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            datetime.combine(expiration, time(0, 0))
        ).date()

        if (
            today == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit(
                "pre-expiration time stop",
                self.Portfolio[self.held_symbol].Quantity
            )

    def _submit_exit(self, reason, quantity):
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._order_ticket_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by higher-priority exit.")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(f"Exit submitted: {reason}, {self.held_symbol}")

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None and
            self._order_ticket_open(self.entry_ticket)
        )

    def _order_ticket_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_symbol} at {self.entry_price:.4f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug(f"Entry order ended: {order_event.Status}")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug(f"Exit order ended: {order_event.Status}")
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentEvent):
        self.Debug("Unexpected option assignment detected; liquidating SPY equity.")
        if self.Portfolio[self.spy].Quantity != 0:
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
        self.blocked_entry_date = self.Time.date()

    def OnExerciseOrder(self, exercise_event: OrderEvent):
        self.Debug("Unexpected option exercise detected; liquidating SPY equity.")
        if self.Portfolio[self.spy].Quantity != 0:
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
        self.blocked_entry_date = self.Time.date()


