from AlgorithmImports import *
from collections import defaultdict
from datetime import datetime, date, time, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(1, 365)
        )

        self.fast_closes = []
        self.slow_closes = []

        self.minute_bars = {}
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.Portfolio[self.spy_symbol].Invested:
            self.Debug("Unexpected SPY equity position; liquidating assignment/exercise.")
            self.Liquidate(self.spy_symbol, "Unexpected exercise or assignment")

        if self.held_option is not None:
            expiry = self._expiration_date(self.held_option)

            if expiry <= current_date:
                self.no_entry_date = current_date
                self._submit_exit("Expiration protection")
            else:
                self._check_time_stop(current_date, expiry)
                self._check_profit_target(slice)

        bar = slice.Bars.get(self.spy_symbol)
        if bar is not None:
            self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_end = bar.EndTime
        if local_end.tzinfo is not None:
            local_end = local_end.astimezone().replace(tzinfo=None)

        bar_date = local_end.date()
        bar_time = local_end.time()

        if not (time(9, 31) <= bar_time <= time(16, 0)):
            return

        end_minute = (local_end.minute // 5) * 5
        if end_minute == 0:
            end_minute = 60

        bucket_end = datetime(
            bar_date.year,
            bar_date.month,
            bar_date.day,
            local_end.hour,
            end_minute
        )

        if bucket_end.minute == 60:
            bucket_end = bucket_end.replace(
                hour=bucket_end.hour + 1,
                minute=0
            )

        key = bucket_end
        self.minute_bars.setdefault(key, {})[local_end] = bar

        completed_keys = [
            k for k in self.minute_bars
            if k <= local_end and k.time().minute in (0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55)
        ]

        for completed_key in sorted(completed_keys):
            bars = self.minute_bars.pop(completed_key)

            expected = [
                completed_key - timedelta(minutes=i)
                for i in range(4, -1, -1)
            ]

            if any(t not in bars for t in expected):
                continue

            self._on_five_minute_close(
                completed_key,
                [bars[t] for t in expected],
                slice
            )

    def _on_five_minute_close(self, end_time, bars, slice: Slice):
        close = float(bars[-1].Close)

        previous_ready = len(self.slow_closes) >= 20
        previous_fast = (
            sum(self.slow_closes[-5:]) / 5.0
            if len(self.slow_closes) >= 5 else None
        )
        previous_slow = (
            sum(self.slow_closes[-20:]) / 20.0
            if len(self.slow_closes) >= 20 else None
        )

        self.slow_closes.append(close)
        self.fast_closes.append(close)

        if len(self.slow_closes) > 20:
            self.slow_closes.pop(0)
        if len(self.fast_closes) > 20:
            self.fast_closes.pop(0)

        if not previous_ready:
            return

        current_fast = sum(self.fast_closes[-5:]) / 5.0
        current_slow = sum(self.slow_closes[-20:]) / 20.0

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if not bullish_cross:
            return

        if not (time(9, 45) <= end_time.time() <= time(14, 30)):
            return

        self._try_entry(slice, close)

    def _try_entry(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self._ticket_finished(self.entry_ticket):
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain))

        future_expirations = sorted({
            self._expiration_date(contract.Symbol)
            for contract in contracts
            if self._expiration_date(contract.Symbol) > today
        })

        if not future_expirations:
            self.Debug("Skipped entry: no valid expiration.")
            return

        selected_expiration = future_expirations[0]
        minimum_strike = spy_price * 1.01

