from AlgorithmImports import *
from datetime import timedelta


class SpyLongCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 370)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None

        self.pending_signal_time = None
        self.expiration_block_date = None
        self.assignment_handled = False

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, self.consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        if self.fast.IsReady:
            self.previous_fast = float(self.fast.Current.Value)
        if self.slow.IsReady:
            self.previous_slow = float(self.slow.Current.Value)

        self.fast.Update(IndicatorDataPoint(bar.EndTime, bar.Close))
        self.slow.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        bullish = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        bar_time = bar.EndTime.time()
        if bullish and (
            (bar_time.hour == 9 and bar_time.minute >= 45)
            or (10 <= bar_time.hour <= 13)
            or (bar_time.hour == 14 and bar_time.minute <= 30)
        ):
            self.pending_signal_time = bar.EndTime

    def OnData(self, slice):
        self.HandleUnexpectedAssignmentOrExercise()

        if self.held_contract is not None:
            self.EvaluateExit(slice)

        if self.pending_signal_time is not None:
            signal_time = self.pending_signal_time
            if self.Time == signal_time:
                self.pending_signal_time = None
                self.TryEnter(slice)

    def TryEnter(self, slice):
        today = self.Time.date()

        if self.expiration_block_date == today:
            return

        if self.held_contract is not None:
            return

        if self.entry_ticket is not None and self.IsOrderOpen(self.entry_ticket):
            return

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped selection: current SPY price unavailable.")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            for key, candidate_chain in slice.OptionChains.items():
                if key == self.option_symbol:
                    chain = candidate_chain
                    break

        if chain is None:
            self.Debug("Skipped selection: no option chain.")
            return

        current_date = self.Time.date()
        contracts = list(chain.Contracts.Values)

        future_expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > current_date
        })

        if not future_expirations:
            self.Debug("Skipped selection: no valid future expiration.")
            return

        expiration_date = future_expirations[0]
        minimum_strike = 1.01 * float(spy_bar.Close)

        candidates = [
            contract
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration_date
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"strike={selected.Strike} expiry={expiration_date}"
        )

    def EvaluateExit(self, slice):
        symbol = self.held_contract
        holding = self.Portfolio[symbol]

        if not holding.Invested:
            return

        expiration_date = symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiration_date:
            self.expiration_block_date = today
            self.SubmitExit(symbol, "Expiration-day liquidation")
            return

        prior_trading_day = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours
        while not exchange_hours.IsDateOpen(prior_trading_day):
            prior_trading_day -= timedelta(days=1)

        if today == prior_trading_day and self.Time.time() >= time(15, 45):
            self.SubmitExit(symbol, "Pre-expiration time stop")
            return

        quote = slice.QuoteBars.get(symbol)
        if quote is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.SubmitExit(symbol, "50 percent profit target")

    def SubmitExit(self, symbol, reason):
        self.expiration_block_date = (
            self.expiration_block_date
            if self.expiration_block_date == self.Time.date()
            else self.expiration_block_date
        )

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {symbol} ({reason})")

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_contract = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_contract} "
                    f"price={self.entry_price:.4f}"
                )

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(f"Exit filled: {order_event.Symbol}")

                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_contract = None
                    self.entry_price = None
                    self.exit_ticket = None
                    self.entry_ticket = None

        if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
                and self.held_contract is None
            ):
                self.entry_ticket = None

    def HandleUnexpectedAssignmentOrExercise(self):
        event = self.CurrentSlice
        message = ""

        if event is not None:
            message = str(getattr(event, "Message", ""))

        for order_event in self.Transactions.GetOrderEvents():
            event_message = str(getattr(order_event, "Message", ""))
            is_assignment = bool(getattr(order_event, "IsAssignment", False))
            is_exercise = bool(getattr(order_event, "IsExercise", False))

            if (
                is_assignment
                or is_exercise
                or "assignment" in event_message.lower()
                or "exercise" in event_message.lower()
            ):
                self.expiration_block_date = self.Time.date()
                self.Debug("Unexpected option exercise or assignment handled.")

        equity_quantity = self.Portfolio[self.spy_symbol].Quantity
        if equity_quantity != 0:
            if not self.assignment_handled:
                self.Debug("Unexpected SPY equity position liquidated.")
                self.assignment_handled = True
            self.MarketOrder(
                self.spy_symbol,
                -equity_quantity,
                tag="Liquidate unexpected exercise or assignment equity"
            )
        else:
            self.assignment_handled = False

    @staticmethod
    def IsOrderOpen(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

