    def HandleUnexpectedAssignmentOrExercise(self):
        event = self.CurrentSlice
        message = ""

        if event is not None:
            message = str(getattr(event, "Message", ""))

        for order_event in self.Transactions.GetOrderEvents():
            event_message = str(getattr(order_event, "Message", ""))
            is_assignment = bool(getattr(order_event, "IsAssignment", False))
            is_exercise = bool(getattr(order_event, "IsExercise", False))

            if (
