        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_key = None
        self.bucket_bars = []
        self.bucket_times = set()

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_block_date = None
        self.assignment_handled_for_date = None

    def OnData(self, slice):
        self._handle_expiration_and_equity(slice)

        if self.spy.Symbol in slice.Bars:
            self._process_minute_bar(slice.Bars[self.spy.Symbol], slice)

        if self.held_symbol is not None:
            self._evaluate_exits(slice)

    def _process_minute_bar(self, bar, slice):
        now = self.Time
        local_time = now.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        minute_end = now.replace(second=0, microsecond=0)

        if minute_end.time() <= time(9, 35):
            bucket_end = now.replace(
                hour=9, minute=35, second=0, microsecond=0
            )
        else:
            elapsed_minutes = (
                minute_end.hour * 60 + minute_end.minute
                - (9 * 60 + 35)
            )
            bucket_end = now.replace(
                second=0,
                microsecond=0
            ) + timedelta(minutes=(5 - elapsed_minutes % 5) % 5)

        key = (bucket_end.date(), bucket_end)

        if self.bucket_key is not None and key != self.bucket_key:
            self._finalize_bucket(slice)

        if self.bucket_key != key:
            self.bucket_key = key
            self.bucket_bars = []
            self.bucket_times = set()

        self.bucket_bars.append(bar)
        self.bucket_times.add(minute_end)

    def _finalize_bucket(self, slice):
        if self.bucket_key is None:
            return

        bucket_date, bucket_end = self.bucket_key
        expected_times = {
            bucket_end - timedelta(minutes=i)
            for i in range(5)
        }

        if (
            len(self.bucket_bars) == 5
            and self.bucket_times == expected_times
        ):
            consolidated_close = self.bucket_bars[-1].Close
            self._process_five_minute_close(
