        self,
        bucket_date,
        bucket_end,
        close,
        slice
    ):
        if bucket_end.date() != bucket_date:
            return

        old_fast = self.previous_fast
        old_slow = self.previous_slow

        self.closes.append(float(close))

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(
            list(self.closes)[-self.fast_period:]
        ) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        bullish_cross = (
            old_fast is not None
            and old_slow is not None
            and old_fast <= old_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bucket_end.time() <= time(14, 30)):
            return

        if bucket_date == self.expiration_block_date:
            return

        if self._option_holding_exists() or self._entry_order_open():
            return

        self._enter_call(slice)

