            f"Call entry submitted: {selected.Symbol}; "
            f"expiry {expiration}"
        )

    def _evaluate_exits(self, slice):
        if self.held_symbol is None or not self._option_holding_exists():
            return

        held_contract = None

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol == self.held_symbol:
                    held_contract = contract
                    break
            if held_contract is not None:
                break

