            quote_midpoint = None
        else:
            bid = held_contract.BidPrice
            ask = held_contract.AskPrice
            quote_midpoint = (
                (bid + ask) / 2.0
                if bid > 0 and ask > 0
                else None
            )

        if (
            quote_midpoint is not None
            and self.entry_price is not None
            and quote_midpoint >= 1.5 * self.entry_price
        ):
            self._submit_exit("50% profit target")
            return

        expiry_date = self.held_symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Canceling prior exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Call exit submitted: {reason}")

    def _handle_expiration_and_equity(self, slice):
        today = self.Time.date()

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if today >= expiry_date:
                self.expiration_block_date = today
                self._submit_exit("expiration processing safeguard")

        spy_quantity = self.Portfolio[self.spy.Symbol].Quantity
        if spy_quantity != 0:
            if self.assignment_handled_for_date != today:
                self.Debug(
                    "Unexpected SPY equity position; liquidating immediately"
                )
                self.assignment_handled_for_date = today
            self.MarketOrder(
                self.spy.Symbol,
                -spy_quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            ):
                if order_event.FillQuantity > 0:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"Call entry filled at {self.entry_price:.4f}"
                    )

            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Call entry order canceled or invalid")
                if not self._option_holding_exists():
                    self.held_symbol = None
                    self.entry_price = None
                    self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Call position liquidated")
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None

        message = str(getattr(order_event, "Message", "")).lower()
        if "assignment" in message or "exercise" in message:
            self.Debug("Unexpected exercise or assignment detected")

    def _option_holding_exists(self):
        return (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Quantity > 0
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _previous_trading_day(self, date_value):
        return self.spy.Exchange.Hours.GetPreviousTradingDay(date_value)

