        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(1, 730)
        )
        self.option = option

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket = None
        self.bucket_closes = []
        self.bucket_count = 0

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._process_expiration()

        if self.held_option is not None and self.entry_price is not None:
            self._evaluate_profit_target(slice)
            self._evaluate_time_stop()

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._update_five_minute_bar(bar, slice)

    def _update_five_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        if end_time.tzinfo is not None:
            end_time = end_time.replace(tzinfo=None)

        if end_time.time() <= datetime.strptime("09:30", "%H:%M").time():
            return
        if end_time.time() > datetime.strptime("16:00", "%H:%M").time():
            return

        bucket_minute = ((end_time.minute + 4) // 5) * 5
        bucket_hour = end_time.hour
        if bucket_minute >= 60:
            bucket_minute -= 60
            bucket_hour += 1

        bucket = end_time.replace(
            hour=bucket_hour,
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.current_bucket is None:
            self.current_bucket = bucket

        if bucket != self.current_bucket:
            if self.bucket_count == 5:
                self._on_five_minute_close(
                    self.current_bucket,
                    self.bucket_closes[-1],
                    slice
                )

            self.current_bucket = bucket
            self.bucket_closes = []
            self.bucket_count = 0

        self.bucket_closes.append(float(bar.Close))
        self.bucket_count += 1

    def _on_five_minute_close(self, end_time: datetime, close: float, slice: Slice):
        self.closes.append(close)
        if len(self.closes) < 20:
            return

        fast = sum(list(self.closes)[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish:
            return

        if not (datetime.strptime("09:45", "%H:%M").time()
                <= end_time.time()
                <= datetime.strptime("14:30", "%H:%M").time()):
            return

        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None:
            status = self.entry_ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted,
                           OrderStatus.PartiallyFilled):
                return

        self._select_and_enter(slice, close)

    def _select_and_enter(self, slice: Slice, spy_price: float):
        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped selection: no option chain.")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain.Contracts.Values))

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug("Skipped selection: no valid expiration.")
            return

        expiration = expirations[0]
        threshold = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug("Skipped selection: no call at a qualifying strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price <= 0:
            return

        held_contract = None
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(self.held_option)
            if contract is not None:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.5 * self.entry_price:
            return

        self._submit_exit("50% profit target")

    def _evaluate_time_stop(self):
        if self.held_option is None:
            return

        expiry = self.held_option.ID.Date.date()
        previous_trading_day = expiry - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self._submit_exit("expiration-eve time stop")

    def _process_expiration(self):
        if self.held_option is None:
            return

        if self.Time.date() >= self.held_option.ID.Date.date():
            self.blocked_entry_date = self.Time.date()
            self._submit_exit("expiration processing")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted,
                           OrderStatus.PartiallyFilled):
                self.exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderType == OrderType.OptionExercise:
            self.Debug("Unexpected option exercise or assignment detected.")
            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -quantity,
                    tag="Liquidate unexpected exercise or assignment"
                )
            self.blocked_entry_date = self.Time.date()
            return

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.PartiallyFilled,
                    OrderStatus.Filled
                ):
                    if self.entry_price is None and order_event.FillPrice > 0:
                        self.entry_price = float(order_event.FillPrice)
                        self.held_option = order_event.Symbol
                        self.Debug(
                            "Entry filled: {0} at {1}".format(
                                self.held_option,
                                self.entry_price
                            )
                        )

                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    if order_event.Status != OrderStatus.Filled:
                        self.entry_ticket = None
                return

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    if order_event.Status == OrderStatus.Filled:
                        self.Debug("Exit filled: " + str(order_event.Symbol))
                        self.held_option = None
                        self.entry_price = None
                    self.exit_ticket = None

