        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._liquidate_unexpected_spy_position()
        self._process_expiration()
        self._process_held_position_exit(slice)

        bars = slice.Bars
        if self.spy in bars:
            self._update_five_minute_bar(bars[self.spy])

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self._try_enter(slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_start = minute_bar.Time
        local_time = local_start.time()

        if local_time < datetime.strptime("09:30", "%H:%M").time():
            return
        if local_time >= datetime.strptime("16:00", "%H:%M").time():
            return

        bucket_minute = 30 + ((local_start.hour * 60 + local_start.minute) - (9 * 60 + 30)) // 5 * 5
        bucket_start = local_start.replace(
            hour=bucket_minute // 60,
            minute=bucket_minute % 60,
            second=0,
            microsecond=0
        )

        if self.current_bucket is None:
            self.current_bucket = bucket_start

        if bucket_start != self.current_bucket:
            self._complete_bucket()
            self.current_bucket = bucket_start
            self.bucket_closes = []

        self.bucket_closes.append(float(minute_bar.Close))

        if len(self.bucket_closes) == 5:
            self._complete_bucket()
            self.current_bucket = None
            self.bucket_closes = []

    def _complete_bucket(self):
        if len(self.bucket_closes) != 5:
            self.bucket_closes = []
            return

        close = self.bucket_closes[-1]
        self.closes.append(close)

        if len(self.closes) < 20:
            return

        fast = sum(list(self.closes)[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        if self.previous_fast is not None and self.previous_slow is not None:
            crossover = (
                self.previous_fast <= self.previous_slow
                and fast > slow
            )

            bar_end = self.current_bucket + timedelta(minutes=5)
            end_time = bar_end.time()
            eligible_start = datetime.strptime("09:45", "%H:%M").time()
            eligible_end = datetime.strptime("14:30", "%H:%M").time()

            if crossover and eligible_start <= end_time <= eligible_end:
                self.pending_entry_signal = True

        self.previous_fast = fast
        self.previous_slow = slow

    def _try_enter(self, slice: Slice):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return
        if self.held_symbol is not None:
            return
        if self._entry_order_open():
            return

        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol.Underlying == self.spy:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped selection: no SPY option chain in current Slice.")
            return

        future_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() > today
        })

        if not future_expirations:
            self.Debug("Skipped selection: no qualifying future expiration.")
            return

        expiration = future_expirations[0]
        spy_price = float(self.Securities[self.spy].Price)

        if spy_price <= 0:
            self.Debug("Skipped selection: invalid current SPY price.")
            return

        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no call satisfies the expiration and strike rules.")
