            float(contract.Strike),
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _process_held_position_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        today = self.Time.date()
        now = self.Time.time()

        if (
            self.time_stop_date == today
            and now >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self._submit_exit("Expiration time stop")
            return

        if self.entry_price is None or self._exit_order_open():
            return

        quote = None
        for chain in slice.OptionChains.Values:
            if self.held_symbol in chain:
                quote = chain[self.held_symbol]
                break

        if quote is None:
            return

        bid = float(quote.BidPrice)
        ask = float(quote.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._cancel_exit_order()
            self._submit_exit("50 percent profit target")

    def _process_expiration(self):
        if self.held_symbol is None or self.expiration_date is None:
            return

        today = self.Time.date()
        if today >= self.expiration_date:
            self.blocked_entry_date = today
            if self.Portfolio[self.held_symbol].Quantity > 0:
                self._submit_exit("Expiration protection")
            else:
                self._clear_position_state()

    def _submit_exit(self, tag):
        if self.held_symbol is None:
            return
        if self._exit_order_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=tag
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_symbol, tag))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = self.held_symbol.ID.Date.date()
                self.time_stop_date = self._previous_trading_day(self.expiration_date)
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {} at {:.4f}".format(
                    order_event.Symbol,
                    float(order_event.FillPrice)
                ))
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self._clear_position_state()
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OptionAssignmentOrderEvent):
        self.Debug("Unexpected option assignment/exercise handling.")
        self.blocked_entry_date = self.Time.date()
        self._liquidate_unexpected_spy_position()

    def _liquidate_unexpected_spy_position(self):
        if self.spy not in self.Portfolio:
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise or assignment")

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _cancel_exit_order(self):
        if self._exit_order_open():
            self.Transactions.CancelOrder(
                self.exit_ticket.OrderId,
                "Canceled before replacement exit"
            )
            self.exit_ticket = None

    def _clear_position_state(self):
        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None

