        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_end = None
        self.current_open = None
        self.current_high = None
        self.current_low = None
        self.current_close = None
        self.current_volume = 0

        self.held_option = None
        self.entry_price = None
        self.entry_order_id = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.time_stop_submitted = False

        self.last_date = None
        self.no_entry_today = False
        self.equity_exit_submitted_today = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.last_date != current_date:
            self.last_date = current_date
            self.no_entry_today = False
            self.equity_exit_submitted_today = False

        self._handle_unexpected_spy_equity()
        self._handle_expiration()

        if self.spy in slice.Bars:
            completed_bar = self._consume_minute_bar(slice.Bars[self.spy])

            if completed_bar is not None:
                bar_end, close = completed_bar
                signal = self._update_averages(bar_end, close)

                if signal and not self.no_entry_today:
                    self._try_enter(slice)

        self._evaluate_exits(slice)

    def _consume_minute_bar(self, bar):
        end = bar.EndTime
        local_date = end.date()
        local_time = end.time()

        if local_time <= time(9, 30) or local_time > time(16, 0):
            return None

        session_start = datetime.combine(local_date, time(9, 35))

        if end <= session_start:
            bucket_end = session_start
        else:
            elapsed_minutes = int((end - session_start).total_seconds() // 60)
            bucket_end = session_start + timedelta(
                minutes=(elapsed_minutes // 5) * 5
            )

        completed = None

        if self.current_bucket_end is not None:
            if bucket_end != self.current_bucket_end:
                completed = (
                    self.current_bucket_end,
                    self.current_close
                )
                self._reset_bucket()

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
            self.current_open = bar.Open
            self.current_high = bar.High
            self.current_low = bar.Low
            self.current_close = bar.Close
            self.current_volume = bar.Volume
        else:
            self.current_high = max(self.current_high, bar.High)
            self.current_low = min(self.current_low, bar.Low)
            self.current_close = bar.Close
            self.current_volume += bar.Volume

        if end >= self.current_bucket_end:
            completed = (
                self.current_bucket_end,
                self.current_close
            )
            self._reset_bucket()

        return completed

    def _reset_bucket(self):
        self.current_bucket_end = None
        self.current_open = None
        self.current_high = None
        self.current_low = None
        self.current_close = None
        self.current_volume = 0

    def _update_averages(self, bar_end, close):
        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.slow_closes) < 20:
            return False

        fast = sum(list(self.fast_closes)[-5:]) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        return bullish and eligible_time

    def _try_enter(self, slice):
        if self.held_option is not None:
            return

        if self.entry_ticket is not None or self.entry_order_id is not None:
            return

        chain = self._get_current_chain(slice)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

