        if self.spy in slice.Bars:
            spy_price = slice.Bars[self.spy].Close
        elif self.Securities[self.spy].Price > 0:
            spy_price = self.Securities[self.spy].Price

        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped entry: unavailable SPY price.")
            return

        current_date = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= current_date
        })

        if not expirations:
            self.Debug("Skipped entry: no valid expiration.")
            return

        selected_expiration = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover call entry"
        )
        self.entry_order_id = self.entry_ticket.OrderId
        self.entry_price = None
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _evaluate_exits(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        expiry_date = self.held_option.ID.Date.date()
        prior_trading_day = self._prior_trading_day(expiry_date)

        if self.Time.date() == prior_trading_day and self.Time.time() >= time(15, 45):
            if not self.time_stop_submitted:
                self._submit_exit("expiration time stop")
                self.time_stop_submitted = True
            return

        midpoint = self._current_midpoint(slice, self.held_option)
        if midpoint is None:
            return

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            try:
                if self.exit_ticket.Status not in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket.Cancel("Replacing open exit order")
            except Exception:
                pass

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _handle_expiration(self):
        if self.held_option is None:
            return

        if self.Time.date() >= self.held_option.ID.Date.date():
            self.no_entry_today = True
            self._submit_exit("expiration protection")

    def _handle_unexpected_spy_equity(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0 and not self.equity_exit_submitted_today:
            self.no_entry_today = True
            self.equity_exit_submitted_today = True
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.Debug("Unexpected SPY exercise or assignment; equity liquidated.")

    def _current_midpoint(self, slice, symbol):
        try:
            if slice.QuoteBars.ContainsKey(symbol):
                quote = slice.QuoteBars[symbol]
                bid = quote.Bid.Close
                ask = quote.Ask.Close

                if bid is not None and ask is not None and bid > 0 and ask > 0:
                    return (bid + ask) / 2.0
        except Exception:
            pass

        chain = self._get_current_chain(slice)
        if chain is not None:
            for contract in chain:
                if contract.Symbol == symbol:
                    bid = contract.BidPrice
                    ask = contract.AskPrice
                    if bid > 0 and ask > 0:
                        return (bid + ask) / 2.0

        return None

    def _get_current_chain(self, slice):
        try:
            if slice.OptionChains.ContainsKey(self.option_symbol):
                return slice.OptionChains[self.option_symbol]
        except Exception:
            pass

        try:
            for chain in slice.OptionChains.Values:
                if chain.Symbol == self.option_symbol:
                    return chain
        except Exception:
            pass

        return None

    def _prior_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.entry_ticket = None
                self.time_stop_submitted = False
                self.Debug(
                    "Entry filled: " + str(self.held_option)
                    + " @ " + str(self.entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_order_id = None
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(order_event.Symbol))
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
                self.time_stop_submitted = False
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

