from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_start = None
        self._bucket_bars = []
        self._bucket_last_end = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_date = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        # Prevent an assigned or exercised SPY position from becoming a strategy position.
        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY exercise/assignment position; liquidating SPY.")
            self.Liquidate(self.spy, "Unexpected exercise or assignment")
            self.blocked_date = today

        self._process_expiration_rules(now)

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            self._evaluate_profit_target(slice)

        if (
            self.held_symbol is None
            and self.entry_ticket is None
            and self.blocked_date != today
        ):
            bar = slice.Bars.get(self.spy)
            if bar is not None:
                self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime
        start = end - timedelta(minutes=1)

        if start.time() < time(9, 30) or end.time() > time(16, 0):
            return

        minutes_from_open = int(
            (start.hour * 60 + start.minute) - (9 * 60 + 30)
        )
        bucket_start = start.replace(
            hour=9, minute=30, second=0, microsecond=0
        ) + timedelta(minutes=(minutes_from_open // 5) * 5)

        if self._bucket_start != bucket_start:
            self._bucket_start = bucket_start
            self._bucket_bars = []
            self._bucket_last_end = None

        if (
            self._bucket_last_end is not None
            and start != self._bucket_last_end
        ):
            self._bucket_bars = []

        self._bucket_bars.append(bar)
        self._bucket_last_end = end

        bucket_end = bucket_start + timedelta(minutes=5)
        if end != bucket_end:
            return

        complete = (
            len(self._bucket_bars) == 5
            and self._bucket_last_end == bucket_end
            and all(
                self._bucket_bars[i].EndTime
                == self._bucket_bars[i - 1].EndTime + timedelta(minutes=1)
                for i in range(1, 5)
            )
        )

        if not complete:
            self._bucket_bars = []
            return

        close = self._bucket_bars[-1].Close
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bucket_end, close)
        self.slow.Update(bucket_end, close)

        bullish = (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        eligible_time = time(9, 45) <= bucket_end.time() <= time(14, 30)
        if bullish and eligible_time:
            self._try_enter(slice, close, bucket_end)

        self._bucket_bars = []

    def _try_enter(self, slice: Slice, spy_price: float, bar_end: datetime):
        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.option_canonical:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug("Skipped entry: no valid expiration.")
            return

        # With no expiration target specified, use the nearest future expiration.
        expiration = expirations[0]

        contracts = [
            contract for contract in chain
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = sorted(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug(
            "Entry submitted: {} strike {:.2f} expiry {}.".format(
                selected.Symbol, selected.Strike, expiration
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.option_canonical:
                chain = candidate
                break

        if chain is None:
            return

        contract = None
        for candidate in chain:
            if candidate.Symbol == self.held_symbol:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0 or self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target", cancel_existing=True)

    def _process_expiration_rules(self, now: datetime):
        if self.held_symbol is None:
            return

        security = self.Securities.get(self.held_symbol)
        if security is None:
            return

        expiry_date = security.Symbol.ID.Date.date()
        today = now.date()

        if today >= expiry_date:
            self.blocked_date = today
            self._submit_exit("Expiration protection", cancel_existing=True)
            return

        if (
            today == expiry_date - timedelta(days=1)
            and now.time() >= time(15, 45)
        ):
            self._submit_exit("Pre-expiration time stop", cancel_existing=False)

    def _submit_exit(self, reason: str, cancel_existing: bool):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            open_statuses = [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending,
            ]
            if status in open_statuses:
                if not cancel_existing:
                    return
                self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {}.".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled,
