        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )
        self.option = option

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.pending_bars = []

    def OnFiveMinuteBar(self, sender, bar):
        self.pending_bars.append(bar)

    def OnData(self, data):
        self.HandleUnexpectedEquityPosition()

        current_date = self.Time.date()

        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if current_date >= expiry_date:
                self.blocked_entry_date = current_date
                self.SubmitExit("expiration processing")
            else:
                prior_trading_day = self.PreviousTradingDay(expiry_date)

                if (
                    current_date == prior_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self.SubmitExit("expiration time stop")
                else:
                    self.CheckProfitTarget(data)

        while self.pending_bars:
            bar = self.pending_bars.pop(0)
            self.ProcessFiveMinuteBar(bar, data)

    def ProcessFiveMinuteBar(self, bar, data):
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        current_fast = sum(
            float(self.closes[i]) for i in range(self.fast_period)
        ) / self.fast_period

        current_slow = sum(
            float(self.closes[i]) for i in range(self.slow_period)
        ) / self.slow_period

        bar_end = bar.EndTime
        eligible_time = (
            bar_end.hour > 9
            or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14
            or (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross or not eligible_time:
            return

        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_option is not None or self.EntryOrderIsOpen():
            return

        self.TryEnter(data)

    def TryEnter(self, data):
        chains = [
            chain for chain in data.OptionChains.Values
            if chain.Symbol.Underlying == self.spy
        ]

        if not chains:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        chain = chains[0]
        current_date = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Expiry.date() > current_date
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the rule.")
            return

        expiration = expirations[0]
        spy_price = float(self.Securities[self.spy].Price)

        if spy_price <= 0:
            self.Debug("Skipped entry: current SPY price is unavailable.")
            return

        minimum_strike = 1.01 * spy_price

        contracts = [
            contract for contract in chain.Contracts.Values
            if (
                contract.Expiry.date() == expiration
                and contract.Right == OptionRight.Call
                and float(contract.Strike) >= minimum_strike
            )
        ]

        if not contracts:
            self.Debug(
                "Skipped entry: no call contract satisfies the expiration "
                "and strike rules."
            )
            return

        contracts.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = contracts[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def CheckProfitTarget(self, data):
        if self.held_option is None or self.entry_price is None:
            return

        symbol = self.held_option.Symbol

        if not data.QuoteBars.ContainsKey(symbol):
            return

        quote = data.QuoteBars[symbol]

        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        symbol = self.held_option.Symbol
        quantity = int(self.Portfolio[symbol].Quantity)

        if quantity == 0:
            return

        if self.ExitOrderIsOpen():
            return

        self.exit_ticket = self.MarketOrder(
            symbol,
            -quantity,
            tag="Option exit: " + reason
        )
        self.Debug("Submitted option exit: " + reason)

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_option = self.Securities[order_event.Symbol]
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entered 1 SPY call at fill price "
                    + str(self.entry_price)
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug("Exited SPY call at fill price " + str(order_event.FillPrice))
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None

            if order_event.OrderType == OrderType.OptionExercise:
                self.blocked_entry_date = self.Time.date()
                self.Debug("Unexpected option exercise or assignment handled.")

                if self.Portfolio[self.spy].Quantity != 0:
                    self.MarketOrder(
                        self.spy,
                        -int(self.Portfolio[self.spy].Quantity),
                        tag="Liquidate unexpected assignment"
                    )

        elif (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.entry_ticket = None

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.exit_ticket = None

    def HandleUnexpectedEquityPosition(self):
        quantity = int(self.Portfolio[self.spy].Quantity)

        if quantity != 0:
            self.blocked_entry_date = self.Time.date()
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Liquidate unexpected exercise or assignment"
            )

    def EntryOrderIsOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def ExitOrderIsOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date() if hasattr(candidate, "date") else candidate.date()

