        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_stop_date = None
        self.expiration_processed_date = None

        self.last_spy_price = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        spy_bar = slice.Bars[self.spy] if slice.Bars.ContainsKey(self.spy) else None
        if spy_bar is not None:
            self.last_spy_price = spy_bar.Close
            self._process_minute_bar(spy_bar, slice)

        if self._has_spy_equity_position():
            self.Debug("Unexpected SPY exercise or assignment; liquidating SPY equity.")
            self.Liquidate(self.spy)

        if self.held_option is not None:
            if self.expiration_processed_date != today and today >= self.held_option.ID.Date.date():
                self.expiration_processed_date = today
                self.Debug("Expiration processing: liquidating held option.")
                self._submit_exit("expiration processing")
            elif (
                self.expiration_stop_date == today
                and now.hour > 15 or (
                    self.expiration_stop_date == today
                    and now.hour == 15
                    and now.minute >= 45
                )
            ):
                self._submit_exit("pre-expiration time stop")
            else:
                self._check_profit_target(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = self.Time

        if local_time.hour < 9 or (
            local_time.hour == 9 and local_time.minute < 30
        ) or local_time.hour >= 16:
            return

        if local_time.minute <= 30:
            bucket_end_minute = 35
        else:
            bucket_end_minute = 30 + (
                math.ceil((local_time.minute - 30) / 5.0) * 5
            )

        bucket_end = local_time.replace(
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        if bucket_end != self.bucket_end:
            if self.bucket_end is not None:
                self._finalize_bucket(self.bucket_end, slice)

            self.bucket_end = bucket_end
            self.bucket_prices = {}

        self.bucket_prices[local_time.replace(second=0, microsecond=0)] = bar.Close

        if len(self.bucket_prices) == 5:
