        bucket_start = bucket_end - timedelta(minutes=5)
        expected_times = [
            bucket_start + timedelta(minutes=i) for i in range(1, 6)
        ]

        if any(t not in self.bucket_prices for t in expected_times):
            return

        close = self.bucket_prices[expected_times[-1]]
        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast = sum(self.fast_values) / 5.0
        slow = sum(self.slow_values) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bucket_end.time() <= time(14, 30)):
            return

        if (
            self.held_option is not None
            or self.entry_ticket is not None
            and self.entry_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]
        ):
            return

        self._enter_from_current_chain(slice)

    def _enter_from_current_chain(self, slice: Slice):
        if self.last_spy_price is None or self.last_spy_price <= 0:
            self.Debug("Skipped selection: SPY price unavailable.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        today = self.Time.date()
        valid_expirations = set()

        for chain in chains:
            for contract in chain:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() > today
                ):
                    valid_expirations.add(contract.Expiry.date())

        if not valid_expirations:
            self.Debug("Skipped selection: no valid option expiration.")
            return

        expiration_date = min(valid_expirations)
        minimum_strike = 1.01 * self.last_spy_price
        candidates = []

        for chain in chains:
            for contract in chain:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() == expiration_date
                    and contract.Strike >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        contract = None
        for chain in slice.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]:
                self.entry_ticket.Cancel("Exit condition reached")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.expiration_stop_date = self._preceding_trading_day(
                    self.Time.date(),
                    self.held_option.ID.Date.date()
                )
                self.Debug(
                    f"Entry filled: {self.held_option}, "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.expiration_stop_date = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option exercise or assignment received.")
        self.Liquidate(self.spy)

    def _preceding_trading_day(self, current_date, expiration_date):
        candidate = expiration_date - timedelta(days=1)

        while candidate >= current_date - timedelta(days=365):
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                datetime(candidate.year, candidate.month, candidate.day)
            ):
                return candidate
            candidate -= timedelta(days=1)

        return expiration_date - timedelta(days=1)

    def _has_spy_equity_position(self):
        return self.Portfolio[self.spy].Invested or (
            self.Portfolio[self.spy].Quantity != 0
        )


