from datetime import timedelta

from QuantConnect import Resolution, DataNormalizationMode
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Consolidators import TradeBarConsolidator
from QuantConnect.Orders import OrderStatus, OptionRight


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.RegisterIndicator(self.spy, self.fast_sma, self.consolidator) if False else None
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.fast_sma = self.SMA(self.spy, 5, Resolution.Minute)
        self.slow_sma = self.SMA(self.spy, 20, Resolution.Minute)

        self._fast_values = []
        self._slow_values = []
        self._previous_fast = None
        self._previous_slow = None

        self._current_contracts = {}
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._blocked_entry_date = None
        self._equity_liquidation_ticket = None

    def OnData(self, slice):
        self._current_contracts = {}

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                self._current_contracts[contract.Symbol] = contract

        self._HandleUnexpectedEquityPosition()
        self._HandleExpirationProcessing()
        self._EvaluateMinuteExit()

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            bar_time = bar.EndTime.time()
            if timedelta(hours=9, minutes=30) < bar_time <= timedelta(hours=16):
                self.consolidator.Update(bar)

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = bar.EndTime.time()

        if not (
            timedelta(hours=9, minutes=30)
            <= bar_time
            <= timedelta(hours=16)
        ):
            return

        self._fast_values.append(float(bar.Close))
        self._slow_values.append(float(bar.Close))

        if len(self._fast_values) < 5 or len(self._slow_values) < 20:
            return

        current_fast = sum(self._fast_values[-5:]) / 5.0
        current_slow = sum(self._slow_values[-20:]) / 20.0

        bullish_crossover = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and current_fast > current_slow
        )

        self._previous_fast = current_fast
        self._previous_slow = current_slow

        if not bullish_crossover:
            return

        if not (
            timedelta(hours=9, minutes=45)
            <= bar.EndTime.time()
            <= timedelta(hours=14, minutes=30)
        ):
            return

        self._TryEnterCall()

    def _TryEnterCall(self):
        today = self.Time.date()

        if self._blocked_entry_date == today:
            return

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None and self._IsOpen(self._entry_ticket):
            return

        if not self._current_contracts:
            self.Debug("Skipped entry: no current option chain.")
            return

        current_price = float(self.Securities[self.spy].Price)
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        today_contracts = list(self._current_contracts.values())

        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in today_contracts
                if contract.Expiry.date() > today
            }
        )

        if not expirations:
            self.Debug("Skipped entry: no valid expiration.")
            return

        expiration = expirations[0]
        dte = (expiration - today).days
        if dte <= 0:
            self.Debug("Skipped entry: invalid days to expiration.")
            return

        minimum_strike = current_price * 1.01

        candidates = [
            contract
            for contract in today_contracts
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
