            expiry = self.entry_symbol.ID.Date.date()

            if local_date >= expiry:
                self.no_entry_date = local_date
                self.SubmitExit("expiration processing")
            else:
                previous_trading_day = self.PreviousTradingDay(expiry)
                if (
                    local_date == previous_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self.SubmitExit("expiration time stop")

                self.CheckProfitTarget(slice)

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is not None:
            self.ProcessMinuteBar(spy_bar, slice)

    def ProcessMinuteBar(self, bar: TradeBar, slice: Slice):
        bar_end = bar.EndTime
        session_start = datetime(
            bar_end.year, bar_end.month, bar_end.day, 9, 30
        )

        if bar_end <= session_start or bar_end.time() > datetime(
            bar_end.year, bar_end.month, bar_end.day, 16, 0
        ).time():
            return

        elapsed_minutes = (bar_end - session_start).total_seconds() / 60.0
        bucket_number = int(math.ceil(elapsed_minutes / 5.0))
        bucket_end = session_start + timedelta(minutes=5 * bucket_number)

        if self.current_bucket_end != bucket_end:
            if self.current_bucket_end is not None:
                self.ProcessFiveMinuteBar(
                    self.current_bucket_end,
                    self.current_close,
                    slice
                )

            self.current_bucket_end = bucket_end
            self.current_open = bar.Open
            self.current_high = bar.High
            self.current_low = bar.Low
            self.current_close = bar.Close
            self.current_volume = bar.Volume
        else:
            self.current_high = max(self.current_high, bar.High)
            self.current_low = min(self.current_low, bar.Low)
            self.current_close = bar.Close
            self.current_volume += bar.Volume

    def ProcessFiveMinuteBar(self, bar_end: datetime, close: float, slice: Slice):
        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(IndicatorDataPoint(bar_end, close))
        self.slow.Update(IndicatorDataPoint(bar_end, close))

        bullish_crossover = (
            old_fast is not None
            and old_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and old_fast <= old_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_crossover:
            bar_time = bar_end.time()
            eligible = (
                datetime(2000, 1, 1, 9, 45).time()
                <= bar_time
                <= datetime(2000, 1, 1, 14, 30).time()
            )

            if eligible:
                self.TryEnter(slice)

    def TryEnter(self, slice: Slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.entry_symbol is not None:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = self.Securities[self.spy_symbol].Price
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        today = self.Time.date()
        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Right == OptionRight.Call
                and (contract.Expiry.date() - today).days >= 30
            }
        )

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
