            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Call entry submitted: {0}, expiry {1}, strike {2}.".format(
                selected.Symbol, expiry, selected.Strike
            )
        )

    def CheckProfitTarget(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self.entry_symbol),
            None
        )
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= self.entry_price * 1.5:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason: str):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = -holding.Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.entry_symbol, quantity)
        self.Debug(
            "Call exit submitted: {0}; reason: {1}.".format(
                self.entry_symbol, reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if (
                    order_event.Status == OrderStatus.Filled
                    and order_event.FillQuantity > 0
                ):
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Call entry filled: {0} at {1}.".format(
                            self.entry_symbol, self.entry_price
                        )
                    )

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Call exit filled: {0} at {1}.".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )
                    self.entry_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                "Unexpected option exercise or assignment: {0}.".format(
                    order_event.Symbol
                )
            )
            self.Liquidate(self.spy_symbol)

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy_symbol]
        if holding.Invested:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.Liquidate(self.spy_symbol)

    def PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)
        return candidate

    @staticmethod
    def IsOpen(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )
