from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute, Market.USA, True, False)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute, Market.USA, True)
        self.option = option
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)

        self.current_bucket_start = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.time_stop_date = None
        self.no_entry_today = False

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.no_entry_today and today != getattr(self, "_no_entry_date", today):
            self.no_entry_today = False

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(today)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            five_minute_bar = self._update_five_minute_bar(spy_bar)
            if five_minute_bar is not None:
                self._process_five_minute_bar(five_minute_bar, slice)

        self._evaluate_exit_conditions(slice)

    def _update_five_minute_bar(self, minute_bar):
        bar_time = minute_bar.Time
        if bar_time.hour < 9 or (bar_time.hour == 9 and bar_time.minute < 30):
            return None
        if bar_time.hour > 16 or (bar_time.hour == 16 and bar_time.minute > 0):
            return None

        bucket_minute = bar_time.minute - (bar_time.minute % 5)
        bucket_start = bar_time.replace(
            minute=bucket_minute, second=0, microsecond=0
        )

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start

        if bucket_start != self.current_bucket_start:
            completed = self._complete_bucket(self.current_bucket_start)
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = {
                bar_time: minute_bar
            }
            return completed

        self.current_bucket_bars[bar_time] = minute_bar
        return None

    def _complete_bucket(self, bucket_start):
        expected_times = [
            bucket_start + timedelta(minutes=i) for i in range(5)
        ]

        if set(self.current_bucket_bars.keys()) != set(expected_times):
            self.current_bucket_bars = {}
            return None

        bars = [self.current_bucket_bars[t] for t in expected_times]
        self.current_bucket_bars = {}

        open_price = bars[0].Open
        high_price = max(bar.High for bar in bars)
        low_price = min(bar.Low for bar in bars)
        close_price = bars[-1].Close
        volume = sum(bar.Volume for bar in bars)

        return TradeBar(
            bucket_start,
            self.spy,
            open_price,
            high_price,
            low_price,
            close_price,
            volume,
            timedelta(minutes=5)
        )

    def _process_five_minute_bar(self, bar, slice):
