    def _ProcessMinuteBar(self, minute_bar: TradeBar, slice: Slice):
        end_time = self._AsNewYork(minute_bar.EndTime)
        minute_start = end_time - timedelta(minutes=1)

        if not (time(9, 30) <= minute_start.time() < time(16, 0)):
            return

        bucket_minute = minute_start.minute - (minute_start.minute % 5)
        bucket_start = minute_start.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self._bucket_start is not None and bucket_start != self._bucket_start:
            self._FinalizeBucket()

        if self._bucket_start is None:
            self._bucket_start = bucket_start
            self._bucket_bars = {}

        if bucket_start != self._bucket_start:
