        if not holding.Invested:
            return

        if self._is_expiration_time_stop():
            self._submit_exit("Expiration time stop")
            return

        quote = data.QuoteBars.get(self.held_symbol)
        if quote is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return
