        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_submitted = True

    def _handle_expiration_processing(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
            self.no_entry_date = self.Time.date()
            self._submit_exit("Expiration processing liquidation")

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment handling: liquidating SPY."
            )
            self.Liquidate(self.spy, "Unexpected exercise or assignment")
            self.no_entry_date = self.Time.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.held_expiry = (
                        self.Securities[self.held_symbol].Symbol.ID.Date.date()
                    )
                    self.Debug(
                        f"Entry filled: {self.held_symbol} "
                        f"at {self.entry_price}"
                    )
                    self.entry_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.None_
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol} "
                        f"at {order_event.FillPrice}"
                    )
                    self.held_symbol = None
                    self.held_expiry = None
                    self.entry_price = None
                    self.exit_ticket = None
                    self.exit_submitted = False
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None
                    self.exit_submitted = False

        message = str(getattr(order_event, "Message", ""))
        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        if is_assignment or "assign" in message.lower() or "exercis" in message.lower():
            self.Debug(
                "Unexpected exercise or assignment event received; "
                "liquidating resulting SPY position."
            )
            self.no_entry_date = self.Time.date()
            if self.Portfolio[self.spy].Quantity != 0:
                self.Liquidate(self.spy, "Unexpected exercise or assignment")

