        if self.held_symbol is None or self.exit_submitted:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self._is_expiration_time_stop():
            self._submit_exit("Expiration time stop")
            return

        quote = data.QuoteBars.get(self.held_symbol)
        if quote is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return
        if self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _is_expiration_time_stop(self):
        if self.held_expiry is None:
            return False

        previous_trading_day = self.held_expiry - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        return (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        )

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_submitted:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.exit_ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_submitted = True

    def _handle_expiration_processing(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
            self.no_entry_date = self.Time.date()
            self._submit_exit("Expiration processing liquidation")

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment handling: liquidating SPY."
            )
            self.Liquidate(self.spy, "Unexpected exercise or assignment")
            self.no_entry_date = self.Time.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
