        # Treat any such holding as unexpected exercise or assignment.
        spy_holding = self.Portfolio[self.spy]
        if spy_holding.Invested:
            self.Debug("Unexpected SPY exercise/assignment; liquidating equity.")
            self.MarketOrder(self.spy, -spy_holding.Quantity)

        # Prevent entries on a day when expiration processing has begun.
        if self.held_option is not None:
            expiry = self.held_option.ID.Date.date()

            if current_date >= expiry:
                self.no_entry_date = current_date
                self._submit_exit("expiration processing")
            elif (
                current_date == expiry - timedelta(days=1)
                and self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("expiration time stop")

            self._evaluate_profit_target(slice)

        if self.spy in slice.Bars:
            self._process_spy_minute(slice.Bars[self.spy], slice)

    def _process_spy_minute(self, bar, slice):
        end = self.Time.replace(second=0, microsecond=0)

        if end.time() <= time(9, 30) or end.time() > time(16, 0):
            return

        if self.aggregate_date != end.date():
            self.aggregate_date = end.date()
            self.aggregate_end = None
            self.aggregate_bars = {}

        minute = end.minute
        bucket_end_minute = ((minute - 1) // 5 + 1) * 5
        bucket_end = end.replace(minute=0) + timedelta(minutes=bucket_end_minute)

        if self.aggregate_end is None or bucket_end != self.aggregate_end:
            self.aggregate_end = bucket_end
            self.aggregate_bars = {}

        self.aggregate_bars[end] = bar

        if end != self.aggregate_end:
            return

        expected_times = [
            self.aggregate_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(t not in self.aggregate_bars for t in expected_times):
            self.aggregate_bars = {}
            return

        close = self.aggregate_bars[self.aggregate_end].Close
        self._process_consolidated_close(close, self.aggregate_end, slice)
        self.aggregate_bars = {}

