from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.fast_sum = 0.0
        self.slow_sum = 0.0
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiration = None
        self.no_entry_date = None

    def OnData(self, slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()
        self._handle_held_position_exits(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        bar_time = bar.Time

        if bar_time.time() < time(9, 30) or bar_time.time() >= time(16, 0):
            return

        current_bucket = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = current_bucket

        if current_bucket != self.bucket_start:
            self._process_completed_five_minute_bar(slice)
            self.bucket_start = current_bucket
            self.bucket_bars = []

        self.bucket_bars.append(bar)

    def _process_completed_five_minute_bar(self, slice):
        if self.bucket_start is None:
            return

        bars = self.bucket_bars
        if len(bars) != 5:
            self.bucket_bars = []
            return

        expected_time = self.bucket_start
        for bar in bars:
            if bar.Time != expected_time:
                self.bucket_bars = []
                return
            expected_time += timedelta(minutes=1)

        close = float(bars[-1].Close)

        if len(self.closes) == self.slow_period:
            self.slow_sum -= self.closes[0]

        self.closes.append(close)
        self.slow_sum += close

        if len(self.closes) >= self.fast_period:
            self.fast_sum = sum(list(self.closes)[-self.fast_period:])
            current_fast = self.fast_sum / self.fast_period
        else:
            current_fast = None

        if len(self.closes) >= self.slow_period:
            current_slow = self.slow_sum / self.slow_period
        else:
            current_slow = None

        bar_end = self.bucket_start + timedelta(minutes=5)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        bullish_cross = (
            current_fast is not None
            and current_slow is not None
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        if (
            bullish_cross
            and eligible_time
            and self.no_entry_date != self.Time.date()
            and self.held_symbol is None
            and not self._entry_order_is_open()
        ):
            self._try_enter(slice)

        if current_fast is not None and current_slow is not None:
            self.previous_fast = current_fast
            self.previous_slow = current_slow

        self.bucket_bars = []

    def _try_enter(self, slice):
        if self.spy_option.Symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no SPY option chain.")
            return

        chain = slice.OptionChains[self.spy_option.Symbol]
        today = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() > today
