                self.bucket_bars = []
                return
            expected_time += timedelta(minutes=1)

        close = float(bars[-1].Close)

        if len(self.closes) == self.slow_period:
            self.slow_sum -= self.closes[0]

        self.closes.append(close)
        self.slow_sum += close

