from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(-100, 100, 0, 365)

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_order = None
        self.exit_order = None
        self.held_option = None
        self.entry_price = None

        self.current_date = None
        self.no_entry_today = False

    def OnData(self, slice: Slice):
        today = self.Time.date()
        if self.current_date != today:
            self.current_date = today
            self.no_entry_today = False

        self._handle_unexpected_equity_position()

        if self.held_option is not None:
            if today >= self.held_option.ID.Date.date():
                self.no_entry_today = True
                self._liquidate_option("expiration processing")
            else:
                self._evaluate_option_exit(slice)

        signal = self._process_spy_minute(slice)

        if signal and not self.no_entry_today:
            self._try_enter(slice)

    def _process_spy_minute(self, slice: Slice):
        try:
            bar = slice.Bars.get(self.spy.Symbol)
        except Exception:
            bar = None

        if bar is None:
            return False

        local_end = bar.EndTime
        if local_end.tzinfo is not None:
            local_end = local_end.replace(tzinfo=None)

        regular_start = local_end.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        regular_end = local_end.replace(
            hour=16, minute=0, second=0, microsecond=0
        )

        if local_end <= regular_start or local_end > regular_end:
            return False

        minute_end = local_end.replace(second=0, microsecond=0)
        offset = (5 - minute_end.minute % 5) % 5
        bucket_end = minute_end + timedelta(minutes=offset)

        completed = False
        completed_end = None
        completed_close = None

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            completed, completed_end, completed_close = self._complete_bucket(
                self.bucket_end
            )
            self.bucket_bars = {}

        self.bucket_end = bucket_end
        self.bucket_bars[minute_end] = bar

        if minute_end == bucket_end:
            completed, completed_end, completed_close = self._complete_bucket(
                bucket_end
            )
            self.bucket_bars = {}

        if not completed:
            return False

        self.fast_values.append(completed_close)
        self.slow_values.append(completed_close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return False

        fast = sum(self.fast_values) / 5.0
        slow = sum(self.slow_values) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = completed_end.time()
        eligible = (
            datetime.strptime("09:45", "%H:%M").time()
            <= end_time
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        return bullish and eligible

    def _complete_bucket(self, bucket_end):
        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(t not in self.bucket_bars for t in expected):
            return False, None, None

        bars = [self.bucket_bars[t] for t in expected]
        return True, bucket_end, bars[-1].Close

    def _try_enter(self, slice: Slice):
        if self.held_option is not None:
            return
        if self._order_is_open(self.entry_order):
            return

        try:
            spy_bar = slice.Bars.get(self.spy.Symbol)
            spy_price = spy_bar.Close if spy_bar is not None else self.Securities[
                self.spy.Symbol
            ].Price
        except Exception:
            spy_price = self.Securities[self.spy.Symbol].Price

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        chain = self._get_option_chain(slice)
        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug("Skipped entry: no valid expiration")
            return

        expiration = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_order = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} strike {:.2f} expiry {}".format(
                selected.Symbol, selected.Strike, expiration
            )
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.entry_price is None or self._order_is_open(self.exit_order):
            return

        quote = self._get_current_quote(slice, self.held_option.Symbol)
        if quote is not None:
            bid, ask = quote
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.5 * self.entry_price:
                    self._cancel_exit_order()
                    self._liquidate_option("profit target")
                    return

        expiry = self.held_option.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.hour >= 15
            and self.Time.minute >= 45
        ):
            self._liquidate_option("expiration time stop")

    def _liquidate_option(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity == 0:
            return

        self._cancel_exit_order()
        self.exit_order = self.MarketOrder(
            self.held_option.Symbol, -quantity
        )
        self.Debug("Exit submitted ({}): {}".format(reason, self.held_option.Symbol))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order is not None and order_event.OrderId == self.entry_order.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.Securities[order_event.Symbol]
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.entry_order = None

        if self.exit_order is not None and order_event.OrderId == self.exit_order.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.exit_order = None
                self.held_option = None
                self.entry_price = None

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.no_entry_today = True
            self.MarketOrder(self.spy.Symbol, -quantity)
            self.Debug(
                "Unexpected exercise or assignment: liquidating SPY equity"
            )

    def _get_option_chain(self, slice: Slice):
        try:
            chain = slice.OptionChains.get(self.spy_option.Symbol)
            if chain is not None:
                return chain
        except Exception:
            pass

        try:
            values = slice.OptionChains.Values
            for chain in values:
                return chain
        except Exception:
            pass

        try:
            for chain in slice.OptionChains.values():
                return chain
        except Exception:
            return None

        return None

    def _get_current_quote(self, slice: Slice, symbol):
        try:
            quote = slice.QuoteBars.get(symbol)
        except Exception:
            quote = None

        if quote is None:
            return None

        try:
            return quote.Bid.Close, quote.Ask.Close
        except Exception:
            return None

    def _cancel_exit_order(self):
        if self._order_is_open(self.exit_order):
            self.exit_order.Cancel("Replaced by liquidation order")
        self.exit_order = None

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        try:
            return ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
        )
        except Exception:
            return False

    def _previous_trading_day(self, expiration_date):
        expiry = datetime(
            expiration_date.year,
            expiration_date.month,
            expiration_date.day
        )

        try:
            previous = self.Securities[
                self.spy.Symbol
            ].Exchange.Hours.GetPreviousTradingDay(expiry)
            return previous.date()
        except Exception:
            previous = expiry - timedelta(days=1)
            while previous.weekday() >= 5:
                previous -= timedelta(days=1)
            return previous.date()

