from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyBullishCallStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end_minute = None
        self.bucket_bars = {}

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.no_entry_date is not None and self.no_entry_date != current_date:
            self.no_entry_date = None

        self._handle_unexpected_equity_position()

        if self.held_symbol is not None:
            expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            if current_date >= expiry:
                self.no_entry_date = current_date
                self._submit_exit("expiration processing")
            else:
                self._evaluate_exits(slice, expiry)

        if self.spy in slice.Bars:
            completed_bar = self._update_five_minute_bar(slice.Bars[self.spy])

            if completed_bar is not None:
                self._evaluate_entry_signal(completed_bar, slice)

    def _update_five_minute_bar(self, minute_bar):
        local_time = self.Time
        if local_time.date() != self.bucket_date:
            self.bucket_date = local_time.date()
            self.bucket_end_minute = None
            self.bucket_bars = {}

        if local_time.time() < time(9, 31) or local_time.time() > time(16, 0):
            return None

        minute = local_time.hour * 60 + local_time.minute
        bucket_end = ((minute - 30 + 4) // 5) * 5 + 30

        if self.bucket_end_minute is None:
            self.bucket_end_minute = bucket_end
        elif bucket_end != self.bucket_end_minute:
            completed = self._complete_bucket()
            self.bucket_end_minute = bucket_end
            self.bucket_bars = {}
            self.bucket_bars[minute] = minute_bar
            return completed

        self.bucket_bars[minute] = minute_bar
        return None

    def _complete_bucket(self):
        if self.bucket_end_minute is None:
            return None

        expected = set(range(self.bucket_end_minute - 4, self.bucket_end_minute + 1))
        if set(self.bucket_bars.keys()) != expected:
            return None

        bars = [self.bucket_bars[m] for m in sorted(expected)]
        return TradeBar(
            self.Time.date(),
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

    def _evaluate_entry_signal(self, five_minute_bar, slice):
        self.closes.append(float(five_minute_bar.Close))

        if len(self.closes) < 20:
            return

        fast = sum(list(self.closes)[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = self.Time.time()
        eligible_time = time(9, 45) <= bar_end <= time(14, 30)

        if not bullish_cross or not eligible_time:
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self._ticket_open(self.entry_ticket):
            return

        chain = self._find_option_chain(slice)
        if chain is None:
            self.Debug("Skipped selection: no option chain.")
            return

        expiration = self._select_expiration(chain)
        if expiration is None:
            self.Debug("Skipped selection: no qualifying expiration.")
            return

        spy_price = float(self.Securities[self.spy].Price)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Symbol.ID.Date.date() == expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.AddOptionContract(selected.Symbol, Resolution.Minute)
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _find_option_chain(self, slice):
        if not slice.OptionChains:
            return None

        for chain in slice.OptionChains.Values:
            return chain

        return None

    def _select_expiration(self, chain):
        today = self.Time.date()
        expirations = sorted({
            contract.Symbol.ID.Date.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Symbol.ID.Date.date() - today).days >= 1
        })

        return expirations[0] if expirations else None

    def _evaluate_exits(self, slice, expiration):
        if self.held_symbol is None or self.entry_price is None:
            return

        current_date = self.Time.date()
        previous_trading_day = self._previous_trading_day(expiration)

        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self._ticket_open(self.exit_ticket):
            return

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != self.held_symbol:
                    continue

                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= 1.50 * self.entry_price:
                        self._submit_exit("50 percent profit target")
                return

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._ticket_open(self.exit_ticket):
            return

        if self.entry_ticket is not None and self._ticket_open(self.entry_ticket):
            return

        if self.Transactions.GetOpenOrders(self.held_symbol):
            for order in self.Transactions.GetOpenOrders(self.held_symbol):
                if order.Id != self.entry_ticket.OrderId:
                    self.Transactions.CancelOrder(order.Id)

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                quantity,
                tag=reason
            )
            self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderType == OrderType.OptionExercise:
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment handling.")
            self._handle_unexpected_equity_position()
            return

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                "Entry filled: " +
                str(self.held_symbol) +
                " at " +
                str(self.entry_price)
            )

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: " + str(order_event.Symbol))
            self.held_symbol = None
            self.entry_price = None
            self.exit_ticket = None
            self.entry_ticket = None

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId and
            order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]
        ):
            self.entry_ticket = None

    def _handle_unexpected_equity_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_date = self.Time.date()
            quantity = -self.Portfolio[self.spy].Quantity
            self.MarketOrder(
                self.spy,
                quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.Debug("Unexpected SPY equity position liquidated.")

    def _previous_trading_day(self, expiration):
        candidate = expiration - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _ticket_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

