            tag="Bullish five-minute crossover entry"
        )

    def _find_option_chain(self, slice):
        if not slice.OptionChains:
            return None

        for chain in slice.OptionChains.Values:
            return chain

        return None

    def _select_expiration(self, chain):
        today = self.Time.date()
        expirations = sorted({
            contract.Symbol.ID.Date.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Symbol.ID.Date.date() - today).days >= 1
        })

        return expirations[0] if expirations else None

    def _evaluate_exits(self, slice, expiration):
        if self.held_symbol is None or self.entry_price is None:
            return

        current_date = self.Time.date()
        previous_trading_day = self._previous_trading_day(expiration)

        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self._ticket_open(self.exit_ticket):
            return

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != self.held_symbol:
                    continue

                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= 1.50 * self.entry_price:
                        self._submit_exit("50 percent profit target")
                return

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._ticket_open(self.exit_ticket):
            return

        if self.entry_ticket is not None and self._ticket_open(self.entry_ticket):
            return

        if self.Transactions.GetOpenOrders(self.held_symbol):
            for order in self.Transactions.GetOpenOrders(self.held_symbol):
                if order.Id != self.entry_ticket.OrderId:
                    self.Transactions.CancelOrder(order.Id)

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                quantity,
                tag=reason
            )
            self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderType == OrderType.OptionExercise:
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment handling.")
            self._handle_unexpected_equity_position()
            return

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                "Entry filled: " +
                str(self.held_symbol) +
                " at " +
                str(self.entry_price)
            )

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: " + str(order_event.Symbol))
            self.held_symbol = None
            self.entry_price = None
            self.exit_ticket = None
            self.entry_ticket = None

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId and
            order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]
        ):
            self.entry_ticket = None

    def _handle_unexpected_equity_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_date = self.Time.date()
            quantity = -self.Portfolio[self.spy].Quantity
            self.MarketOrder(
                self.spy,
                quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.Debug("Unexpected SPY equity position liquidated.")

    def _previous_trading_day(self, expiration):
        candidate = expiration - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _ticket_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

