        if self._exit_ticket is not None and self._IsOpen(self._exit_ticket):
            return

        quantity = -self.Portfolio[self._held_option].Quantity
        if quantity != 0:
            self._CancelOpenExit()
            self._exit_ticket = self.MarketOrder(
                self._held_option,
                quantity
            )
            self.Debug("Expiration/time-stop exit submitted.")

    def _PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)
        return candidate

    def _HandleUnexpectedEquityPosition(self):
        if self.Portfolio[self.spy].Invested:
            self._blocked_entry_date = self.Time.date()
            self.Liquidate(self.spy)
            self.Debug("Unexpected SPY equity position liquidated.")

    def _CancelOpenExit(self):
        if self._exit_ticket is not None and self._IsOpen(self._exit_ticket):
            self._exit_ticket.Cancel("Replacing exit order.")

    def _IsOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_option = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_ticket = None
                self.Debug(
                    "Call entry filled: {0} at {1}".format(
                        self._held_option,
                        self._entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_ticket = None
                self.Debug("Call entry order did not fill.")

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option exit filled.")
                self._held_option = None
                self._entry_price = None
                self._exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._exit_ticket = None

        event_type = str(getattr(order_event, "OrderEventType", ""))
        if "Assignment" in event_type or "Exercise" in event_type:
            self._blocked_entry_date = self.Time.date()
            if self.Portfolio[self.spy].Invested:
                self.Liquidate(self.spy)
            self.Debug("Unexpected option exercise or assignment handled.")

